import { Book } from "@/lib/types";

export const job: Book = {
  id: "job",
  name: "Hiob",
  shortName: "Hiob",
  testament: "old",
  introduction: `Kann man den Sinn von Leid verstehen?\n**Hiob** lebte wahrscheinlich zur Zeit der Patriarchen Isaak und Jakob in einem Gebiet, das später vom Stamm Manasse bewohnt wurde (das Land Uz). Das legen verschiedene Beobachtungen im Buch selbst nahe. Seine Existenz wird in der Bibel außerdem von Hesekiel 14,14.20 und Jakobus 5,11 bestätigt. Aufgeschrieben wurde seine Geschichte von einem ungenannten Verfasser. Vermutet werden Mose oder Salomo. Sein Thema: \"Warum lässt Gott es zu, dass Fromme leiden?\" Wenn man Hiobs Ende bedenkt vermittelt das Buch darüber hinaus auch \"Hoffnung im Leiden\". Die drei Freunde Hiobs, die ihn in seinem Leid besuchten, sagten viel Richtiges. Doch ihre Vermutungen über die Ursache des Leidens trafen im Fall Hiobs nicht zu.\n**Das Buch Hiob** ist ein unvergleichliches literarisches Kunstwerk. Es fällt auch durch seinen Aufbau auf: Anfang und Ende des Buches sind beschreibende Prosa, Hiobs Geschichte: Sein Feind ist der Satan, sein Erlöser ist Gott. Die drei Mittelteile sind in poetischer Sprache verfasst und enthalten Reden: Hiobs Ankläger sind seine drei Freunde; Hiobs Mittler ist Elihu, der vierte Freund; Hiobs Schöpfer ist Gott.\nSeine erste Prüfung, bei der ihm alles genommen wird, besteht Hiob ausgezeichnet, aber in der zweiten, als er selbst angetastet wird, versagt er, denn er verlangt von Gott, dass seine Rechtschaffenheit belohnt wird. Diese auf Werken beruhende Gerechtigkeit kann Gott nicht akzeptieren. Darum stellt er am Ende des Buches sich selbst ihm vor, wodurch Hiob gedemütigt und gerettet wird.\n****Wie man persönliches Leiden völlig falsch verstehen kann und durch das Pochen auf sein Recht dazu kommt, Gott Willkür und Ungerechtigkeit vorzuwerfen.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Im Land Uz* lebte ein Mann namens Hiob*. Dieser Mann war aufrichtig und vollständig Gott ergeben. Er fürchtete Gott und mied das Böse.", heading: "1-2: Vorwort des Autors\nHiob und seine Söhne", footnotes: ["Uz. Der Name des Landes stammt wahrscheinlich von einem der ersten Bewohner, vielleicht einem Enkel Sems (1. Mose 10,23) oder einem Sohn Nahors (1. Mose 22,21).", "Hiob . Der Name war im 2. Jahrtausend v.Chr. im vorderen Orient bekannt. Verschiedene kanaanäische Edelleute hießen so. Er bedeutet wörtlich: \"Wo ist der Vater?\""] },
      { number: 2, text: "Ihm wurden sieben Söhne und drei Töchter geboren." },
      { number: 3, text: "Er besaß 7000 Schafe, 3000 Kamele, 500 Rindergespanne, 500 Eselinnen und sehr viele Sklaven. Er hatte das größte Ansehen von allen Männern im Nahen Osten." },
      { number: 4, text: "Seine Söhne pflegten Gastmähler in ihren Häusern zu halten, wenn sie Geburtstag* hatten. Dann luden sie auch ihre drei Schwestern ein, um mit ihnen zu essen und zu trinken.", footnotes: ["Geburtstag. Wörtlich: jeder an seinem Tag."] },
      { number: 5, text: "Immer, wenn die Tage des Gastmahls vorbei waren, schickte Hiob hin und ließ seine Kinder heiligen. Dann stand er früh am Morgen auf und brachte Gott für jeden von ihnen ein Brandopfer. Er sagte sich nämlich: \"Vielleicht haben meine Kinder gesündigt und sich in ihrem Herzen von Gott losgesagt*.\" So machte es Hiob jedes Mal.", footnotes: ["von Gott losgesagt. Wörtlich: Gott gesegnet. Das ist ein verhüllender Ausdruck und meint wie Hiob 2,5.9 das Gegenteil."] },
      { number: 6, text: "Eines Tages kamen die Söhne Gottes*, um sich vor Jahwe einzufinden. Unter ihnen war auch der Satan*.", heading: "Gott und seine \"Söhne\"", footnotes: ["Söhne Gottes sind Geistwesen, die erschaffen wurden, bevor das materielle Universum existierte (Hiob 38,7), also Engel.", "Satan. Hebräisch: der Widersacher. Er hat die gleiche Natur wie die Engel, aber sein Charakter ist völlig anders geworden."] },
      { number: 7, text: "Da sagte Jahwe zum Satan: \"Wo kommst du her?\" – \"Ich habe die Erde durchstreift\", erwiderte der Satan, \"und bin auf ihr hin und her gezogen.\"" },
      { number: 8, text: "Da sagte Jahwe zum Satan: \"Hast du auf meinen Diener Hiob geachtet? Auf der Erde gibt es keinen zweiten wie ihn. Er ist mir aufrichtig und vollständig ergeben. Er fürchtet Gott und meidet das Böse.\"" },
      { number: 9, text: "Der Satan erwiderte Jahwe: \"Ist Hiob etwa umsonst so gottesfürchtig?" },
      { number: 10, text: "Du beschützt ihn doch von allen Seiten, sein Haus und alles, was er hat! Du lässt ja all sein Tun gelingen, und seine Herden breiten sich im Land aus." },
      { number: 11, text: "Versuch es doch einmal und lass ihn alles verlieren, was er hat! Ob er dir dann nicht ins Gesicht hinein flucht?\"" },
      { number: 12, text: "Da sagte Jahwe zum Satan: \"Pass auf! Alles, was er hat, ist in deiner Hand. Nur ihn selbst taste nicht an!\" Da entfernte sich der Satan aus der Gegenwart Jahwes." },
      { number: 13, text: "Eines Tages saßen Hiobs Söhne und Töchter im Haus ihres erstgeborenen Bruders, um zu essen und Wein zu trinken.", heading: "Hiob und seine Söhne" },
      { number: 14, text: "Da kam ein Bote zu Hiob und berichtete ihm: \"Wir pflügten gerade mit den Rindern und die Eselinnen weideten nebenan," },
      { number: 15, text: "da fielen die Sabäer* über uns her und raubten alle Tiere. Alle Knechte haben sie erschlagen. Nur ich bin entkommen, ich allein, um es dir zu berichten.\"", footnotes: ["Die Sabäer kamen vielleicht aus dem Gebiet um Saba bei Dedan im nördlichen Teil Arabiens."] },
      { number: 16, text: "Während dieser noch redete, kam ein anderer und berichtete: \"Ein Feuer Gottes ist vom Himmel gefallen. Es hat das Kleinvieh und die Knechte verbrannt und völlig aufgezehrt. Nur ich bin entkommen, ich allein, um es dir zu berichten.\"" },
      { number: 17, text: "Während dieser noch redete, kam ein anderer und berichtete: \"Drei Horden der Chaldäer* haben unsere Kamelherden überfallen und weggetrieben. Alle Knechte haben sie erschlagen. Nur ich bin entkommen, ich allein, um es dir zu berichten.\"", footnotes: ["Chaldäer. Hier sind wohl die nomadischen Vorfahren der späteren Eroberer Babylons gemeint, die dann den Kern von Nebukadnezzars Imperium bildeten."] },
      { number: 18, text: "Während dieser noch redete, kam ein anderer und berichtete: \"Deine Söhne und Töchter aßen und tranken Wein im Haus ihres erstgeborenen Bruders." },
      { number: 19, text: "Da kam ein Sturm von jenseits der Wüste her und packte das Haus an allen vier Ecken. Es stürzte über den jungen Leuten zusammen und hat sie alle erschlagen. Nur ich bin entkommen, ich allein, um es dir zu berichten.\"" },
      { number: 20, text: "Da stand Hiob auf, riss sein Obergewand ein* und schor sich den Kopf. Dann ließ er sich zur Erde sinken und beugte sich nieder.", footnotes: ["riss ... ein. Als Zeichen von Trauer und Entsetzen riss man vom Halsausschnitt an das Gewand mit einem heftigen Ruck etwa eine Handlänge ein."] },
      { number: 21, text: "\"Nackt bin ich aus dem Leib meiner Mutter gekommen, / nackt gehe ich wieder dahin. / Jahwe hat gegeben und hat es wieder genommen. / Gelobt sei der Name Jahwes.\"" },
      { number: 22, text: "Bei alldem sündigte Hiob nicht und schrieb Gott nichts Ungebührliches zu." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Eines Tages kamen die Söhne Gottes, um sich vor Jahwe einzufinden. Unter ihnen war auch der Satan.", heading: "Gott und seine \"Söhne\"" },
      { number: 2, text: "Da sagte Jahwe zum Satan: \"Wo kommst du her?\" \"Ich habe die Erde durchstreift\", erwiderte dieser, \"und bin auf ihr hin und her gezogen.\"" },
      { number: 3, text: "Da sagte Jahwe zum Satan: \"Hast du auf meinen Diener Hiob geachtet? Auf der Erde gibt es keinen zweiten wie ihn. Er ist mir aufrichtig und vollständig ergeben. Er fürchtet Gott und meidet das Böse. Und noch immer hält er an seiner Rechtschaffenheit fest. Du hast mich aufgereizt, ihn ohne Grund zu verderben.\"" },
      { number: 4, text: "Da erwiderte der Satan Jahwe: \"Haut um Haut! Alles, was der Mensch hat, gibt er für sein Leben." },
      { number: 5, text: "Taste ihn doch einmal selber an! Ob er dir dann nicht ins Gesicht hinein flucht?\"" },
      { number: 6, text: "Da sagte Jahwe zum Satan: \"Pass auf! Er ist in deiner Hand. Nur das Leben musst du ihm lassen!\"" },
      { number: 7, text: "Da entfernte sich der Satan aus der Gegenwart Jahwes und ließ an Hiob von Kopf bis Fuß böse Geschwüre aufbrechen.", heading: "Hiob und seine Frau" },
      { number: 8, text: "Dieser setzte sich in einen Aschehaufen, nahm eine Scherbe in die Hand und begann, sich damit zu kratzen." },
      { number: 9, text: "Da sagte seine Frau zu ihm: \"Hältst du immer noch an deiner Gottergebenheit fest? Fluche* Gott und stirb!\"", footnotes: ["Fluche. Wörtlich: Segne. Hier wie in Hiob 1,5; 2,5 ein verhüllender Ausdruck. Satan benutzte Hiobs Frau, wie er Eva gebrauchte, um Adam zu versuchen."] },
      { number: 10, text: "Doch er sagte zu ihr: \"Dummes Geschwätz! Das Gute nehmen wir von Gott an, sollten wir da nicht auch das Böse annehmen?\" Bei alldem kam kein sündiges Wort über seine Lippen." },
      { number: 11, text: "Hiob hatte drei Freunde: Elifas von Teman*, Bildad von Schuach* und Zofar von Naama*. Sie hörten von dem Unglück, das Hiob getroffen hatte, und verabredeten sich, ihn gemeinsam zu besuchen. Sie wollten ihm ihr Beileid bezeugen und ihn trösten.", heading: "Hiobs Freunde kommen", footnotes: ["Elifas von Teman. Beides sind edomitische Namen. Teman war auch ein Ort im späteren Edom.", "Bildad von Schuach. Bildad könnte ein Nachkomme von Schuach, dem jüngsten Sohn von Abraham und Ketura sein, der einen Ort nach seinem Namen gründete (1. Mose 25,2).", "Zofar von Naama. Diese Namen kommen in der Bibel sonst nicht vor und sind auch außerbiblisch bisher nicht bekannt."] },
      { number: 12, text: "Schon von fern sahen sie ihn, aber sie erkannten ihn nicht. Da fingen sie an, laut zu weinen. Sie rissen ihre Obergewänder ein, warfen Staub in die Luft und streuten ihn auf ihre Köpfe." },
      { number: 13, text: "Dann setzten sie sich zu Hiob auf die Erde. Sieben Tage und Nächte lang blieben sie so sitzen. Keiner sagte ein Wort zu ihm, denn sie sahen, dass der Schmerz sehr groß war." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Dann erst begann Hiob zu sprechen und verfluchte den Tag seiner Geburt.", heading: "3-31: Die Reden der Freunde\nErste Runde (3-14)\nHiob verwünscht den Tag seiner Geburt" },
      { number: 2, text: "Er sagte:" },
      { number: 3, text: "\"Es verschwinde der Tag, an dem ich geboren bin, / und die Nacht, die sagte: 'Ein Knabe kam zur Welt!'" },
      { number: 4, text: "Finsternis sei dieser Tag! / Gott da oben frage nicht nach ihm, / nie scheine über ihm das Licht!" },
      { number: 5, text: "Mögen Finsternis und Dunkel ihn besitzen, / dichte Wolken über ihm stehen! / Die Finsternis ersticke sein Licht!" },
      { number: 6, text: "Jene Nacht – das Dunkel soll sie holen, / damit sie nicht im Jahreslauf erscheint! / Sie soll zu keinem Monat gehören!" },
      { number: 7, text: "Unfruchtbar sei jene Nacht, / kein Jubel kehre bei ihr ein!" },
      { number: 8, text: "Verwünschen sollen sie die Tageverflucher*, / die fähig sind, den Leviatan* zu reizen!", footnotes: ["Tageverflucher. Okkultisten, die wie Bileam (4. Mose 22-24) Menschen, Dinge und Zeiten verfluchten.", "Leviatan. Ein krokodilähnliches Ungeheuer, hier Symbol einer gottfeindlichen Macht, die die Nacht von Hiobs Geburt hätte verschlingen können."] },
      { number: 9, text: "Finster seien die Sterne ihrer Dämmerung; / sie hoffe auf Licht, doch das bleibe aus, / sie sehe keinen Schimmer vom Morgenrot!" },
      { number: 10, text: "Denn sie hat mir nicht den Mutterschoß versperrt / und das Unglück meinen Augen erspart.\"" },
      { number: 11, text: "\"Warum starb ich nicht bei der Geburt, / als ich aus dem Mutterschoß kam?", heading: "Hiob verwünscht sein Überleben als Säugling" },
      { number: 12, text: "Weshalb kamen mir Knie entgegen, / wozu Brüste, dass ich daran sog?" },
      { number: 13, text: "Dann läge ich jetzt schon und ruhte aus, / dann schliefe ich und hätte Ruh" },
      { number: 14, text: "mit Königen und Räten des Landes, / die sich verödete Grabmäler bauten;" },
      { number: 15, text: "oder mit Fürsten, reich an Gold, / die ihre Häuser mit Silber füllten." },
      { number: 16, text: "Oder als verscharrte Fehlgeburt wäre ich nicht da, / wie ein Kind, das das Licht nie sah." },
      { number: 17, text: "Dort endet das Wüten der Bösen, / dort ruhen die Erschöpften aus." },
      { number: 18, text: "Gefangene sind frei von Sorgen, / hören das Geschrei des Antreibers nicht." },
      { number: 19, text: "Die Kleinen sind dort wie die Großen, / und der Sklave ist frei von seinem Herrn.\"" },
      { number: 20, text: "\"Warum gibt er dem Leidenden Licht / und Leben denen, die verbittert sind;", heading: "Hiob verwünscht den Umstand, weiterleben zu müssen" },
      { number: 21, text: "die auf den Tod warten, doch der bleibt aus; / die nach ihm scharren mehr als nach Schätzen;" },
      { number: 22, text: "die sich freuen würden, wären sie im Grab. / Sie würden jubeln und wären entzückt." },
      { number: 23, text: "Warum gibt er dem Mann Leben, / den Gott ringsum eingezäunt hat / und dessen Weg verborgen ist?" },
      { number: 24, text: "Bevor ich noch esse, kommt mir das Seufzen, / und wie Wasser ergießt sich mein Stöhnen." },
      { number: 25, text: "Wovor mir Angst war, das hat mich getroffen, / wovor mir graute, das kam über mich." },
      { number: 26, text: "Hatte ich nicht Frieden, nicht Ruhe, nicht Rast? / Und dann kam das Toben.\"" },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Jetzt gab Elifas von Teman Antwort.", heading: "Erste Rede des Elifas: seine These" },
      { number: 2, text: "\"Verstimmt es dich, wenn man ein Wort an dich versucht? / Aber wer könnte seine Worte noch hemmen?" },
      { number: 3, text: "So viele hast du unterwiesen / und müde Hände stark gemacht." },
      { number: 4, text: "Deine Worte richteten Strauchelnde auf, / weichen Knien gabst du wieder Kraft." },
      { number: 5, text: "Doch jetzt kommt's über dich, und du gibst auf, / dich trifft es, und du bist verstört." },
      { number: 6, text: "Ist nicht deine Gottesfurcht dein Trost, / dein tadelloses Leben deine Zuversicht?" },
      { number: 7, text: "Bedenke doch: 'Wer kam je als Unschuldiger um, / wo sind Aufrichtige beseitigt worden?'" },
      { number: 8, text: "So wie ich es sah: / Die Unheil pflügen / und Unrecht säen, / die ernten es auch." },
      { number: 9, text: "Durch Gottes Atem kommen sie um, / vom Hauch seines Zorns vergehen sie." },
      { number: 10, text: "Der Löwe brüllt nicht mehr, der Fresser verstummt, / Gott bricht ihnen die Zähne aus." },
      { number: 11, text: "Der Löwe kommt um aus Mangel an Raub, / die Jungen der Löwin werden zerstreut.\"" },
      { number: 12, text: "\"Zu mir aber stahl sich sein Wort, / mein Ohr vernahm ein Flüstern davon.", heading: "Woher Elifas seine Erkenntnis hat" },
      { number: 13, text: "In Gedanken aus nächtlicher Schau, / wenn Tiefschlaf über Menschen fällt," },
      { number: 14, text: "kam Furcht und Zittern über mich / und schreckte meine Glieder auf." },
      { number: 15, text: "Ein kalter Hauch berührte mein Gesicht, / die Haare standen mir zu Berg." },
      { number: 16, text: "Da stand er, den ich nicht kannte. / Vor meinen Augen war eine Gestalt, / und ich hörte ein Flüstern:" },
      { number: 17, text: "'Kann ein Mensch gerecht sein vor Gott, / ein Mann vor seinem Schöpfer rein?" },
      { number: 18, text: "Selbst seinen Dienern traut er nicht, / wirft auch seinen Engeln Irrtum vor;" },
      { number: 19, text: "wie viel mehr dann den Geschöpfen aus Lehm, / die aus dem Staub hervorgegangen sind, / die man wie Motten zerdrückt," },
      { number: 20, text: "die man von Morgen bis Abend erschlägt? / Unbeachtet gehen sie für immer dahin." },
      { number: 21, text: "Gott bricht ihre Zelte ab, / sie sterben und wissen nicht einmal wie.'\"" },
    ] },
    { number: 5, verses: [
      { number: 1, text: "\"Ruf doch! Antwortet einer? / An wen von den Heiligen wendest du dich?", heading: "Elifas wendet seine These auf Hiob an" },
      { number: 2, text: "Den Narren bringt der Unwille um, / den Dummkopf tötet der Eifer." },
      { number: 3, text: "Einen Narren sah ich Wurzeln schlagen / und verfluchte sogleich seine Wohnstatt." },
      { number: 4, text: "Seine Kinder bleiben fern vom Glück, / man zertritt sie im Tor / und niemand rettet sie." },
      { number: 5, text: "Ein Hungriger verzehrt seine Ernte, / selbst aus den Dornen holt er sie weg. / Durstige lechzen nach seinem Gut." },
      { number: 6, text: "Nicht aus dem Staub geht das Unheil hervor, / Mühsal sprosst nicht aus der Erde." },
      { number: 7, text: "Doch der Mensch ist zur Mühsal geboren, / wie der Funkenwirbel, der aus dem Feuer fliegt.\"" },
      { number: 8, text: "\"Doch ich, ich würde Gott suchen, / ich brächte meine Sache vor den,", heading: "Hiob soll zu Gott umkehren" },
      { number: 9, text: "der Großes und Unergründliches tut, / Wunderbares ohne Zahl; /" },
      { number: 10, text: "der Regen auf die Erde gibt / und Wasser auf die Fluren schickt, /" },
      { number: 11, text: "um Niedrige in die Höhe zu bringen, / Trauernde wieder glücklich zu machen." },
      { number: 12, text: "Er vereitelt die Anschläge der Klugen, / ihre Hände schaffen keinen Erfolg." },
      { number: 13, text: "Er fängt die Weisen in ihrer List* / und stürzt den Ratschlag der Schlauen.", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 1. Korinther 3,19."] },
      { number: 14, text: "Am hellen Tag stoßen sie an wie im Dunkeln / und tappen am Mittag wie in der Nacht." },
      { number: 15, text: "Er aber rettet vor dem Schwert ihres Mundes, / vor der Hand des Starken den Armen." },
      { number: 16, text: "So kann der Schwache Hoffnung haben, / und die Bosheit verschließt ihren Mund.\"" },
      { number: 17, text: "\"Glücklich der Mensch, den Gott bestraft! / Verachte die Zucht des Allmächtigen nicht!", heading: "Dann würde er wiederhergestellt" },
      { number: 18, text: "Denn er fügt Schmerzen zu und verbindet, / er schlägt Wunden, und er heilt sie auch." },
      { number: 19, text: "Aus sechs Nöten reißt er dich heraus, / in sieben tastet dich kein Unglück an." },
      { number: 20, text: "In Hungersnot erlöst er dich vom Sterben, / im Krieg vor dem gewaltsamen Tod." },
      { number: 21, text: "Vor der Geißel böser Zungen schützt er dich, / du musst Gewalt nicht fürchten, wenn sie kommt." },
      { number: 22, text: "Verwüstung und Hunger wirst du verlachen, / vor wilden Tieren hast du keine Angst." },
      { number: 23, text: "Du bist mit den Steinen des Feldes im Bund, / das Raubwild ist im Frieden mit dir." },
      { number: 24, text: "Du wirst sehen, dass dein Zelt im Frieden ist, / und wenn du deine Wohnung prüfst, so fehlt dir nichts." },
      { number: 25, text: "Du wirst sehen, dass deine Nachkommen zahlreich sind, / deine Sprösslinge wie das Kraut auf der Erde." },
      { number: 26, text: "Hoch betagt gehst du ins Grab, wie reifes Korn, das eingefahren wird." },
      { number: 27, text: "Sieh, das haben wir erforscht, so ist es. / Wir haben es gehört, nun merke es dir!\"" },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Da erwiderte Hiob:", heading: "Hiobs zweite Rede: Er entschuldigt seine Worte durch sein Leid" },
      { number: 2, text: "\"Würde doch mein Kummer gewogen, / und mein Unglück dazu auf die Waage gelegt!" },
      { number: 3, text: "Ja, es ist schwerer als der Sand aller Meere. / Darum waren meine Worte unbedacht." },
      { number: 4, text: "Denn die Pfeile des Allmächtigen stecken in mir, / mein Geist hat ihr Gift getrunken, / die Schrecken Gottes greifen mich an." },
      { number: 5, text: "Schreit ein Wildesel denn über dem Gras, / brüllt ein Stier denn, wenn er Futter hat?" },
      { number: 6, text: "Isst man Fades ohne Salz, / ist im Eiweiß* denn Geschmack?", footnotes: ["Eiweiß. Wörtlich: Eibischschleim. Der Schleim der Eibischstaude wurde als Medikament gebraucht."] },
      { number: 7, text: "Ich sträube mich, daran zu rühren, / es ist mir wie verdorbenes Brot.\"" },
      { number: 8, text: "\"Käme doch, was ich begehre, / dass Gott mein Verlangen erfüllt,", heading: "Hiob klagt, dass Gott zuviel von ihm verlangt" },
      { number: 9, text: "dass Gott sich entschließt, mich zu töten, / seine Hand enthemmt und mich ums Leben bringt." },
      { number: 10, text: "So könnte ich mich noch trösten / und jubeln in der grausamen Qual, / denn ich habe die Worte des Heiligen nicht verdeckt." },
      { number: 11, text: "Welche Kraft hätte ich, noch zu hoffen, / was ist das Ziel, für das ich durchhalten soll?" },
      { number: 12, text: "Ist meine Kraft denn Felsenkraft, / ist mein Körper aus Eisen?" },
      { number: 13, text: "In mir ist keine Hilfe mehr, / und was ich kann, ist dahin.\"" },
      { number: 14, text: "\"Wer seinem Freund den Beistand versagt, / fürchtet den Allmächtigen nicht mehr.", heading: "Hiob klagt, dass seine Freunde ihn enttäuschen" },
      { number: 15, text: "Meine Brüder enttäuschen wie ein Wildbach, / wie Wasserläufe, die versickern," },
      { number: 16, text: "die trübe sind vom geschmolzenen Eis, / mit Schneewasser gefüllt." },
      { number: 17, text: "In der Sommerglut sind sie verschwunden, / wenn es heiß wird, versiegen sie." },
      { number: 18, text: "Karawanen biegen ab von ihrem Weg, / folgen ihnen hinauf in die Öde – und verschwinden." },
      { number: 19, text: "Die Karawanen von Tema hielten Ausschau nach ihnen, / die Handelszüge Sabas hofften auf sie." },
      { number: 20, text: "Sie wurden beschämt, weil sie vertrauten, / sie kamen hin und wurden enttäuscht." },
      { number: 21, text: "So seid ihr für mich geworden. / Ihr seht den Jammer und schreckt zurück." },
      { number: 22, text: "Habe ich denn gesagt: / 'Bringt her von eurem Besitz, / kommt, macht mir ein Geschenk," },
      { number: 23, text: "befreit mich aus der Hand des Bedrängers, / zahlt den Erpressern das Lösegeld!'?" },
      { number: 24, text: "Belehrt mich, dann werde ich schweigen, / zeigt mir, wo ich mich irrte!" },
      { number: 25, text: "Wie kränkend sind 'richtige Sprüche', / was tadelt euer Tadel denn?" },
      { number: 26, text: "Wollt ihr etwa Worte tadeln? / Redet der Verzweifelte in den Wind?" },
      { number: 27, text: "Selbst um ein Waisenkind würdet ihr losen, / und euren Freund verschachert ihr." },
      { number: 28, text: "Und jetzt entschließt euch, schaut mich an! / Ich lüge euch doch nicht ins Gesicht." },
      { number: 29, text: "Kehrt um, damit kein Unrecht geschieht, / kehrt um, noch bin ich im Recht!" },
      { number: 30, text: "Ist denn Unrecht auf meiner Zunge? / Schmeckt mein Gaumen das Böse nicht mehr?\"" },
    ] },
    { number: 7, verses: [
      { number: 1, text: "\"Zwangsarbeit ist dem Menschen auf Erden bestimmt, / wie ein Söldner muss er seine Tage verbringen.", heading: "Hiob klagt über sein nichtiges Leben" },
      { number: 2, text: "Wie ein Sklave sich nach Schatten sehnt, / so wartet der Söldner auf seinen Sold." },
      { number: 3, text: "So wurden mir Wochen ohne Ertrag beschert / und Nächte voller Mühsal zugeteilt." },
      { number: 4, text: "Wenn ich liege, sage ich mir: / 'Wann stehe ich endlich wieder auf?' / Doch die Nacht zieht sich dahin, / und ich wälz mich herum, bis es dämmert." },
      { number: 5, text: "Mein Leib ist gekleidet in Maden und Schorf, / meine Haut ist verschorft und eitert." },
      { number: 6, text: "Wie ein Weberschiffchen* fliegen meine Tage, / ganz ohne Hoffnung schwinden sie dahin.", footnotes: ["Weberschiffchen. Länglicher Behälter mit Spule (auf dem der Schussfaden aufgewickelt ist), der zwischen den Kettfäden eines Webstuhls hin und her geschossen wird."] },
      { number: 7, text: "Bedenke, dass mein Leben ein Hauch ist, / mein Auge nie mehr Gutes sehen wird." },
      { number: 8, text: "Wer mich sehen will, / erblickt mich nicht mehr, / sucht mich dein Auge, / bin ich nicht da." },
      { number: 9, text: "Die Wolke löst sich auf und verschwindet, / und wer zu den Toten fährt, steigt nicht wieder auf." },
      { number: 10, text: "Er kehrt nicht mehr in sein Haus zurück, / und seine Stätte kennt ihn nicht mehr.\"" },
      { number: 11, text: "\"So will auch ich meinen Mund nicht zügeln, / will reden in der Angst meines Geistes, / will klagen mit verbitterter Seele.", heading: "Hiob protestiert gegen Gottes Handeln mit ihm" },
      { number: 12, text: "Bin ich ein Ungeheuer oder ein Meer, / dass du eine Wache gegen mich stellst?" },
      { number: 13, text: "Wenn ich sage: 'Mein Bett soll mich trösten, / mein Lager meine Klage ertragen'," },
      { number: 14, text: "so erschreckst du mich mit Träumen, / bringst mich durch Visionen in Angst," },
      { number: 15, text: "so dass ich lieber ersticken wollte, / lieber den Tod, als meine Knochen hier seh." },
      { number: 16, text: "Ich bin es satt! / Ich mag nicht ewig leben. / Lass mich! / Mein Leben ist doch nur ein Hauch." },
      { number: 17, text: "Was ist der Mensch, / dass du ihn groß machst, / dass du acht auf ihn hast," },
      { number: 18, text: "dass du ihn jeden Morgen zur Rechenschaft ziehst, / dass du ihn jeden Augenblick prüfst?" },
      { number: 19, text: "Wann endlich blickst du von mir weg, / dass ich in Ruhe meinen Speichel schlucken kann?" },
      { number: 20, text: "Hab ich gesündigt? Was tat ich dir an, du Wächter der Menschen? / Warum hast du mich zu deiner Zielscheibe gemacht? / Warum werde ich mir selbst zur Last?" },
      { number: 21, text: "Und warum vergibst du mein Vergehen nicht / und erlässt mir meine Schuld? / So lege ich mich jetzt in den Erdenstaub, / und wenn du mich suchst, so bin ich nicht mehr.\"" },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Da entgegnete Bildad von Schuach:", heading: "Erste Rede des Bildad: seine These" },
      { number: 2, text: "\"Wie lange willst du solche Reden noch führen, / wie lange machen deine Worte noch Wind?" },
      { number: 3, text: "Wird Gott die Gerechtigkeit beugen, / krümmt der Allmächtige das Recht?" },
      { number: 4, text: "Haben deine Kinder an ihm gesündigt, / gab er sie in die Gewalt ihrer Schuld." },
      { number: 5, text: "Wenn du Gott eifrig suchst, / zu dem Allmächtigen flehst," },
      { number: 6, text: "wenn du rein und aufrichtig bist, / dann wacht er deinetwegen auf / und stellt die Wohnung deiner Gerechtigkeit her." },
      { number: 7, text: "Dein Anfang wird gering sein, / aber dein Ende sehr groß.\"" },
      { number: 8, text: "\"Frag doch die, die vor dir waren, / achte auf das, was ihre Väter erforschten!", heading: "Woher Bildad seine Erkenntnis nahm" },
      { number: 9, text: "Denn wir sind von gestern und wissen nichts, / wie Schatten gehen unsere Tage dahin." },
      { number: 10, text: "Werden sie dich nicht lehren, / sprechen sie nicht zu dir, / holen Worte aus ihrem Herzen hervor?\"" },
      { number: 11, text: "\"Wächst Schilfrohr, wo kein Sumpf ist? / Schießt Riedgras ohne Wasser auf?", heading: "Bildad wendet seine These auf Hiob an" },
      { number: 12, text: "Noch grünt es, ist nicht reif zum Schnitt, / da verdorrt es schon vor allem Gras." },
      { number: 13, text: "So ist das Leben derer, die Gott vergessen, / so schwindet die Zukunft des Bösen." },
      { number: 14, text: "Seine Zuversicht ist wie ein dünner Faden, / sein Vertrauen ein Spinngewebe." },
      { number: 15, text: "Er stützt sich auf sein Haus, doch es gibt nach, / er klammert sich daran, doch es steht nicht fest." },
      { number: 16, text: "In vollem Saft steht einer in der Sonne, / seine Zweige überwuchern den Garten," },
      { number: 17, text: "seine Wurzeln schlingen sich über Geröll, / zwischen Steinen hält er sich fest." },
      { number: 18, text: "Reißt man ihn von seiner Stelle weg, / so verleugnet sie ihn: 'Dich sah ich noch nie.'" },
      { number: 19, text: "Ja, das bleibt vom Glück seines Weges, / und aus dem Staub sprießen andere auf." },
      { number: 20, text: "Gott verwirft den Schuldlosen nicht, / doch die Hand des Boshaften lässt er los." },
      { number: 21, text: "Er wird deinen Mund noch mit Lachen erfüllen / und deine Lippen mit Jubel." },
      { number: 22, text: "Die dich hassen, müssen sich Schande anziehen. / Das Zelt dieser Gottlosen ist dann nicht mehr da.\"" },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Da gab ihm Hiob zur Antwort:", heading: "Hiobs dritte Rede: Wie kann ein Mensch gerecht sein vor Gott?" },
      { number: 2, text: "\"Gewiss, ich weiß, dass es so ist! / Wie könnte ein Mensch im Recht sein vor Gott?" },
      { number: 3, text: "Hätte er Lust, sich mit ihm zu streiten, / könnte er ihm auf tausend nicht eines erwidern." },
      { number: 4, text: "Er hat ein weises Herz und große Kraft. / Wer trotzt ihm und bleibt unversehrt?" },
      { number: 5, text: "Er versetzt Berge, / und sie merken es nicht; / in seinem Zorn stürzt er sie um." },
      { number: 6, text: "Die Erde schreckt er von ihrem Ort auf, / sodass ihre Säulen erzittern." },
      { number: 7, text: "Er spricht zur Sonne, dann strahlt sie nicht auf, / er kann sogar die Sterne versiegeln." },
      { number: 8, text: "Er allein, er spannt den Himmel aus, / schreitet auf den Wogen des Meeres." },
      { number: 9, text: "Er hat den großen Bären gemacht, / den Orion und das Siebengestirn / und alle Sterne des Südens." },
      { number: 10, text: "Er schafft so Großes, Unergründliches, / tut Wunder, die niemand mehr zählt.\"" },
      { number: 11, text: "\"Geht er an mir vorbei, ich sehe ihn nicht, / zieht er vorüber, ich bemerke ihn nicht.", heading: "Wer will Gott an etwas hindern?" },
      { number: 12, text: "Reißt er weg, wer hält ihn zurück? / Wer darf ihm sagen: 'Was machst du da?'" },
      { number: 13, text: "Gott hält seinen Zorn nicht zurück, / unter ihm haben sich Rahabs* Helfer geduckt.", footnotes: ["Rahab. Hier ein urzeitliches Meerungeheuer, ein Bild gottfeindlicher Mächte."] },
      { number: 14, text: "Wie könnte ich ihm Rede stehen, / meine Worte wählen vor ihm?" },
      { number: 15, text: "Und wäre ich im Recht, / ich könnte ihm nichts erwidern. / Anflehen müsste ich ihn, meinen Richter." },
      { number: 16, text: "Riefe ich und er gäbe mir Antwort, / ich könnte nicht glauben, dass er auf mich hört!" },
      { number: 17, text: "Er, der mich im Sturm zermalmt, / meine Wunden grundlos vermehrt." },
      { number: 18, text: "Er erlaubt mir nicht, Atem zu schöpfen, / sondern füllt mich mit bitterem Leid." },
      { number: 19, text: "Fragst du nach Stärke: Schau da! / Und nach Recht: Wer lädt mich vor?" },
      { number: 20, text: "Wäre ich auch im Recht, mein Mund würde mich verdammen; / wäre ich vollkommen, er beugte mich doch." },
      { number: 21, text: "Ich bin schuldlos, / ich sorge mich nicht, / ich verachte mein Leben." },
      { number: 22, text: "Es ist alles einerlei. Darum sage ich: / 'Er bringt den Schuldlosen wie den Schuldigen um!" },
      { number: 23, text: "Wenn die Geißel plötzlich tötet, / lacht er über die Verzweiflung der Unschuldigen." },
      { number: 24, text: "Er hat die Erde einem Schurken gegeben / und alle Richter blind gemacht. / Wenn nicht er, wer dann?'\"" },
      { number: 25, text: "\"Schneller als Läufer jagen meine Tage davon, / sie fliehen und sehen kein Glück.", heading: "Es gibt keinen Schlichter zwischen uns" },
      { number: 26, text: "Wie Schilfrohrboote gleiten sie vorbei, / wie der Sturz eines Adlers auf seine Beute." },
      { number: 27, text: "Wenn ich denke: 'Ich will meine Klage vergessen, / ich blicke heiter, mach ein anderes Gesicht'," },
      { number: 28, text: "dann graut mir vor meinen Schmerzen. / Ich weiß, du sprichst mich nicht frei." },
      { number: 29, text: "Ich soll eben schuldig sein. / Was mühe ich mich umsonst?" },
      { number: 30, text: "Würde ich mich mit Schneewasser waschen, / meine Hände mit Lauge säubern," },
      { number: 31, text: "dann würdest du mich in die Grube tauchen, / dass selbst meine Gewänder sich ekeln vor mir." },
      { number: 32, text: "Denn er ist nicht ein Mensch wie ich, / dass ich ihm antworten könnte / und wir gingen miteinander vor Gericht." },
      { number: 33, text: "Kein Schlichter vermittelt zwischen uns / und legt seine Hand auf uns beide." },
      { number: 34, text: "Er nehme seine Rute von mir weg, / sein Schrecken soll mich nicht mehr ängstigen." },
      { number: 35, text: "Dann kann ich reden und muss ihn nicht fürchten, / dann hätte ich dazu keinen Grund.\"" },
    ] },
    { number: 10, verses: [
      { number: 1, text: "\"Mein Leben ekelt mich an, / ich lasse meiner Klage freien Lauf, / will reden, so bitter wie ich bin.", heading: "Keiner kann mich aus Gottes Hand retten" },
      { number: 2, text: "Ich sagte zu Gott: 'Verdamm mich doch nicht! / Lass mich wissen, warum du gegen mich kämpfst!" },
      { number: 3, text: "Gefällt es dir, dass du unterdrückst, / das Werk deiner Hände verachtest / und den Rat der Gottlosen erleuchtest?" },
      { number: 4, text: "Hast du Augen wie ein Mensch, / siehst du so wie ein Mensch?" },
      { number: 5, text: "Sind deine Tage wie beim Menschen begrenzt, / deine Jahre wie die eines Mannes?" },
      { number: 6, text: "Du suchst nach meiner Schuld / und forschst nach meiner Sünde," },
      { number: 7, text: "obwohl du weißt, dass ich nicht schuldig bin / und keiner mich aus deiner Hand reißt." },
      { number: 8, text: "Deine Hände haben mich gestaltet und gemacht, / ganz und gar – und nun verschlingst du mich." },
      { number: 9, text: "Bedenke doch: Wie Ton hast du mich gestaltet, / und jetzt führst du mich zum Staub zurück?" },
      { number: 10, text: "Hast du mich nicht verschüttet wie Milch, / wie Käse mich gerinnen lassen?" },
      { number: 11, text: "Haut und Fleisch hast du mir angezogen, / mich mit Knochen und Sehnen durchflochten." },
      { number: 12, text: "Leben und Gnade hast du mir geschenkt, / in deiner Obhut war mein Geist." },
      { number: 13, text: "Doch dieses hast du verborgen in dir, / ich weiß, so hattest du es beschlossen." },
      { number: 14, text: "Wenn ich sündigte, würdest du mich belauern, / sprächst mich von meinem Fehler nicht frei." },
      { number: 15, text: "Wenn ich schuldig würde, wehe mir! / Und wäre ich im Recht, / dürfte ich den Kopf nicht heben, / gesättigt mit Schande, / mit Elend getränkt." },
      { number: 16, text: "Sollte ich es dennoch tun, / jagst du mich wie ein Löwe, / gehst wieder unbegreiflich mit mir um," },
      { number: 17, text: "stellst immer neue Zeugen gegen mich auf, / findest Gründe, mir noch mehr zu grollen. / Immer neue Heere führst du gegen mich.'\"" },
      { number: 18, text: "\"Warum ließest du mich aus dem Mutterschoß kommen? / Wenn ich doch gestorben wäre, bevor ein Auge mich sah!", heading: "Warum kam ich aus dem Mutterschoß?" },
      { number: 19, text: "Ich wäre dann, als sei ich nie gewesen, / vom Mutterleib ins Grab gebracht." },
      { number: 20, text: "Mein Leben dauert doch nur wenige Tage. / Er höre auf und lasse von mir, / dass ich ein wenig aufblicken kann," },
      { number: 21, text: "bevor ich ohne Rückkehr gehe / ins Land des Dunkels und der Finsternis," },
      { number: 22, text: "ins Land, so düster wie die schwarze Nacht, / ins Schattenland, wo keine Ordnung ist, / wo heller Tag ist wie die finstere Nacht.\"" },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Da erwiderte Zofar von Naama:", heading: "Erste Rede des Zofar: Hiob, du bist ein Schwätzer!" },
      { number: 2, text: "\"Soll der Wortschwall ohne Antwort sein, / und hat ein Schwätzer einfach Recht?" },
      { number: 3, text: "Lässt dein Gerede Männer verstummen? / Darfst du spotten, ohne dass man's dir verweist?" },
      { number: 4, text: "Sagst du doch: 'Meine Lehre ist klar, / ich bin in Gottes Augen rein!'" },
      { number: 5, text: "Wenn Gott nur reden wollte, / seine Lippen auftun gegen dich" },
      { number: 6, text: "und zeigte dir verborgene Weisheit, / die zu hoch ist für den Verstand! / Dann würdest du erkennen, / dass Gott von deiner Schuld noch manches übersieht.\"" },
      { number: 7, text: "\"Kannst du die Tiefe Gottes erreichen, / die Vollkommenheit des Allmächtigen fassen?", heading: "Was willst du gegen den Allmächtigen?" },
      { number: 8, text: "Sie ist hoch wie der Himmel – was kannst du tun? / Sie ist tiefer als die Welt der Toten – was durchschaust du schon?" },
      { number: 9, text: "Weiter als die Erde ist ihr Maß / und breiter als das Meer." },
      { number: 10, text: "Wenn er vorbeizieht und zupackt, / wenn er zusammentreibt, / wer will ihn daran hindern?" },
      { number: 11, text: "Denn er erkennt die falschen Leute, / sieht das Unrecht, das man nicht achtet." },
      { number: 12, text: "Kommt ein Hohlkopf noch zu Verstand, / wird je ein Wildesel zum Menschen?\"" },
      { number: 13, text: "\"Wenn du dein Herz in Ordnung bringst / und deine Hände zu ihm erhebst –", heading: "Entferne das Böse von dir!" },
      { number: 14, text: "ist Böses in deiner Hand, entferne es / und lass in deinen Zelten kein Unrecht sein –," },
      { number: 15, text: "dann kannst du dein Gesicht ohne Makel erheben, / dann stehst du fest und musst dich nicht fürchten." },
      { number: 16, text: "Dann wirst du die Mühsal vergessen, / wirst an sie denken wie an Wasser, das vorüberfloss." },
      { number: 17, text: "Heller als der Mittag strahlt dein Leben auf, / das Dunkel wird dem Morgen gleich." },
      { number: 18, text: "Du fasst Vertrauen, weil es Hoffnung gibt, / du schaust dich um und legst dich ruhig nieder." },
      { number: 19, text: "Und liegst du da, schreckt keiner dich auf, / und viele suchen deine Gunst." },
      { number: 20, text: "Doch die Augen der Bösen versagen, / sie haben keine Zuflucht mehr, / ihre Hoffnung ist nur noch der Tod.\"" },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Hiob erwiderte:", heading: "Hiob weist alles zurück, was seine Freunde gesagt haben. Sarkastisch: Mit euch stirbt die Weisheit aus!" },
      { number: 2, text: "\"Ja, ihr seid die rechten Leute, / und mit euch stirbt die Weisheit aus!" },
      { number: 3, text: "Auch ich habe Verstand wie ihr, / ich stehe euch nicht nach! / Und wer wüsste das nicht?" },
      { number: 4, text: "Dem eigenen Freund bin ich zum Spott, / ich, der Gott anruft, dass er mich hört. / Ja, der Gerechte, der Fromme wird zum Spott." },
      { number: 5, text: "'Dem Unglück Verachtung!', denkt der Sichere, / 'ein Stoß noch denen, deren Fuß schon wankt!'\"" },
      { number: 6, text: "Um die Zelte der Verwüster steht es gut, / die Gott reizen, leben sicher, / die meinen, sie hätten Gott in der Hand.", heading: "Überlegen: Ich verstehe mehr von Gott als ihr!" },
      { number: 7, text: "Aber frag doch das Vieh, das wird es dich lehren, / die Vögel machen es dir bekannt." },
      { number: 8, text: "Rede zur Erde, sie schärft es dir ein, / die Fische im Meer erzählen es dir." },
      { number: 9, text: "Wer wüsste bei alledem nicht, / dass Jahwes Hand es gemacht hat?" },
      { number: 10, text: "Von seiner Macht hängt alles Leben ab / und der Geist im Leib jedes Menschen." },
      { number: 11, text: "Soll nicht das Ohr die Worte prüfen, / wie der Gaumen eine Speise schmeckt?" },
      { number: 12, text: "Es heißt: 'Bei Greisen ist die Weisheit, / die Einsicht, die durch langes Leben kommt.'" },
      { number: 13, text: "Nein, bei ihm ist Weisheit und Macht, / ihm gehören Einsicht und Rat." },
      { number: 14, text: "Was er abreißt, baut niemand wieder auf, / wen er einsperrt, dem öffnet keiner die Tür." },
      { number: 15, text: "Hält er das Wasser zurück, dann trocknet alles aus, / lässt er es los, zerwühlt es das Land." },
      { number: 16, text: "Bei ihm sind Einsicht und Macht, / ihm gehört, wer irrt und wer in die Irre führt." },
      { number: 17, text: "Ratgeber lässt er barfuß gehen, / und Richter macht er zu Narren." },
      { number: 18, text: "Den Gurt von Königen löst er auf / und lässt ihren Lenden nur den Schurz." },
      { number: 19, text: "Priester führt er entblößt hinweg, / und alte Geschlechter bringt er zu Fall." },
      { number: 20, text: "Bewährten nimmt er die Sprache / und Ältesten die Urteilskraft." },
      { number: 21, text: "Verachtung gießt er auf Edelleute aus, / Starken löst er den Gürtel." },
      { number: 22, text: "Im Dunkel Verborgenes deckt er auf, / selbst die Todesnacht bringt er ans Licht." },
      { number: 23, text: "Er lässt Völker wachsen und vergehen, / er breitet sie aus und rafft sie dann weg." },
      { number: 24, text: "Den Häuptern des Landes nimmt er den Verstand, / lässt sie irren in pfadloser Öde." },
      { number: 25, text: "Sie tappen im Dunkeln ohne ein Licht, / er lässt sie wie Betrunkene taumeln." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Schaut, all das hat mein Auge gesehen, / mein Ohr gehört und sich gemerkt." },
      { number: 2, text: "Was ihr da wisst, das weiß ich auch, / ich stehe euch in nichts nach.\"" },
      { number: 3, text: "\"Doch zum Allmächtigen will ich reden, / mit Gott zu streiten ist mein Wunsch!", heading: "Überheblich: Gott soll mein Richter sein, nicht ihr!" },
      { number: 4, text: "Ihr habt doch nur Pflaster aus Lügen, / Pfuschärzte seid ihr allesamt." },
      { number: 5, text: "Wenn ihr doch endlich schweigen wolltet, / dann hielte man das noch für Weisheit!" },
      { number: 6, text: "Hört euch meine Rechtfertigung an, / merkt auf den Streit meiner Worte!" },
      { number: 7, text: "Wollt ihr Falsches reden für Gott / und Lügen vorbringen für ihn?" },
      { number: 8, text: "Wollt ihr für ihn Partei ergreifen, / Gottes Sache vertreten?" },
      { number: 9, text: "Wird es gut für euch sein, wenn er euch erforscht? / Lässt er sich von euch täuschen wie ein Mensch?" },
      { number: 10, text: "Tadeln, ja tadeln wird er euch, / wenn ihr heimlich Partei ergreift." },
      { number: 11, text: "Erschreckt ihr nicht vor seiner Majestät, / wird die Angst vor ihm euch nicht packen?" },
      { number: 12, text: "Eure Sätze sind nur Sprüche aus Staub, / eure Schilde bestehen aus Ton." },
      { number: 13, text: "Seid still, ich will jetzt reden, / mag über mich kommen, was will." },
      { number: 14, text: "Und wenn ich Kopf und Kragen riskiere, / ich setze mein Leben aufs Spiel!" },
      { number: 15, text: "Und wenn er mich tötet, ich warte auf ihn / und verantworte mich direkt vor ihm." },
      { number: 16, text: "Schon darin sehe ich mein Heil, / denn kein Schurke hat Zutritt bei ihm." },
      { number: 17, text: "Hört mir nur ganz aufmerksam zu, / dass meine Erklärung auch in eure Ohren dringt." },
      { number: 18, text: "Seht, ich bin für den Rechtsstreit gerüstet, / und ich weiß, ich bekomme Recht!" },
      { number: 19, text: "Wer könnte den Prozess gewinnen gegen mich? / Dann wollte ich schweigen und zugrunde gehen.\"" },
      { number: 20, text: "\"Nur zweierlei tu mir nicht an, / dann verberge ich mich nicht vor dir:", heading: "Bitter: Gott, quäle mich doch nicht!" },
      { number: 21, text: "'Nimm deine schwere Hand von mir weg, / und dein Schrecken befalle mich nicht!'" },
      { number: 22, text: "Dann kannst du rufen, und ich antworte dir, / oder ich rede, und du antwortest mir." },
      { number: 23, text: "Wie groß ist meine Schuldenlast bei dir? / Was sind meine Vergehen und Sünden?" },
      { number: 24, text: "Warum verbirgst du dein Gesicht, / behandelst mich wie deinen Feind?" },
      { number: 25, text: "Willst du ein verwehtes Blatt verschrecken, / verfolgst du einen dürren Halm?" },
      { number: 26, text: "Denn Bitteres teilst du mir zu; / für meine Jugendsünden lässt du mich büßen." },
      { number: 27, text: "Du steckst meine Füße in den Block*, / beobachtest all meine Wege / und grenzt mich ein auf Schritt und Tritt,", footnotes: ["Ein hölzerner Block, in den die Füße der Gefangenen eingeschlossen wurden, siehe auch Apostelgeschichte 16,24."] },
      { number: 28, text: "der ich doch wie Moder zerfalle, / wie ein Gewand, das die Motte zerfraß.\"" },
    ] },
    { number: 14, verses: [
      { number: 1, text: "\"Der Mensch, geboren von der Frau, / ist knapp an Tagen und unruhevoll.", heading: "Enttäuscht: Das Leben ist so kurz." },
      { number: 2, text: "Er blüht wie eine Blume auf und verwelkt, / er flieht wie ein Schatten, hat keinen Bestand." },
      { number: 3, text: "Doch über ihn hast du ein waches Auge, / ihn ziehst du vor dein Gericht." },
      { number: 4, text: "Gibt es denn einen Reinen, der von Unreinen stammt? / Nicht einen!" },
      { number: 5, text: "Sind seine Tage bestimmt, / steht die Zahl seiner Monate fest, / hast du ihm die Schranke gesetzt, / die er niemals überschreiten kann," },
      { number: 6, text: "dann schau doch von ihm weg, dass er Ruhe hat, / dass er wie ein Tagelöhner sich seines Tagwerks freuen kann!\"" },
      { number: 7, text: "\"Denn für den Baum gibt es Hoffnung: / Wird er gefällt, so schlägt er wieder aus, / an Trieben fehlt es ihm nicht.", heading: "Verzweifelt: Der Mensch hat keine Hoffnung." },
      { number: 8, text: "Wenn seine Wurzel im Boden altert, / sein Stumpf im Staub abstirbt," },
      { number: 9, text: "so sprosst er wieder vom Duft des Wassers, / treibt Zweige wie ein Pflänzling." },
      { number: 10, text: "Der Starke aber stirbt und ist schwach, / ein Mensch kommt um – und wo ist er?" },
      { number: 11, text: "Wie Wasser aus dem See verschwindet, / wie ein Strom austrocknet und versiegt," },
      { number: 12, text: "so legt der Mensch sich hin und steht nicht mehr auf; / der Himmel vergeht, bevor er erwacht / und geweckt wird aus seinem Schlaf." },
      { number: 13, text: "Ach, dass du mich bei den Toten verstecktest, / mich verbirgst, bis dein Zorn vorüber ist, / mir eine Frist setzt und dann an mich denkst!" },
      { number: 14, text: "Wenn ein Starker stirbt, wird er wieder leben? / Meine Dienstzeit lang wollte ich warten, / bis meine Ablösung käme!" },
      { number: 15, text: "Du würdest rufen und ich gäbe dir Antwort, / du sehntest dich nach dem Werk deiner Hände." },
      { number: 16, text: "Dann zähltest du zwar meine Schritte, / doch du hieltest mir meine Sünden nicht vor." },
      { number: 17, text: "Mein Vergehen wäre ein versiegeltes Bündel, / meine Schuld hättest du übertüncht." },
      { number: 18, text: "Doch auch ein Berg stürzt ein und zerfällt, / und ein Fels rückt von der Stelle." },
      { number: 19, text: "Steine werden vom Wasser zerrieben, / das Erdreich schwemmt ein Wolkenbruch weg, / und die Hoffnung des Menschen machst du kaputt." },
      { number: 20, text: "Du überwältigst ihn, er geht für immer fort, / du entstellst sein Gesicht und schickst ihn weg." },
      { number: 21, text: "Kommen seine Kinder zu Ehren, weiß er es nicht, / kommen sie herunter, merkt er es nicht." },
      { number: 22, text: "Nur sein eigener Körper bereitet ihm Schmerz, / nur um die eigene Seele trauert er noch.\"" },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Da entgegnete Elifas von Teman:", heading: "Zweite Runde (15-21)\nZweite Rede des Elifas: Hiob, du bist ungerecht und anmaßend!" },
      { number: 2, text: "\"Wird ein Weiser windiges Wissen erwidern, / füllt er denn seinen Bauch mit Wind?" },
      { number: 3, text: "Wird er mit nutzlosen Reden rügen, / mit Worten ohne jeglichen Wert?" },
      { number: 4, text: "Du bist es, der die Gottesfurcht zerstört, / du verdirbst die Andacht vor Gott." },
      { number: 5, text: "Deine Schuld belehrt deinen Mund; / du hast eine listige Sprache gewählt." },
      { number: 6, text: "Dein eigner Mund verurteilt dich; nicht ich, / deine Lippen sagen gegen dich aus." },
      { number: 7, text: "Hat man dich als ersten Menschen gezeugt, / warst du eher als die Hügel da?" },
      { number: 8, text: "Hast du in Gottes Ratsversammlung gelauscht / und die Weisheit an dich gerissen?" },
      { number: 9, text: "Was weißt du, das wir nicht schon wüssten? / Was verstehst du mehr als wir?" },
      { number: 10, text: "Auch bei uns ist ein Graukopf, ein Greis, / älter als dein eigener Vater." },
      { number: 11, text: "Ist Gottes Trost dir zu gering, / ein Wort, das sanft zu dir kommt?" },
      { number: 12, text: "Was reißt dein Herz dich hin, / was rollen deine Augen," },
      { number: 13, text: "dass du dein Schnauben gegen Gott kehrst, / Reden aus deinem Mund fahren lässt?\"" },
      { number: 14, text: "\"Was ist der Mensch, dass er rein sein könnte, / wie sollte der gerecht sein, den eine Frau gebar?", heading: "Vor Gott ist niemand gerecht" },
      { number: 15, text: "Selbst seinen Heiligen vertraut er nicht, / und der Himmel ist in seinen Augen nicht rein." },
      { number: 16, text: "Wie denn der Abscheuliche, der Angefaulte, / der Mann, der Unrecht wie das Wasser trinkt?\"*", footnotes: ["Das hatte Elifas schon einmal gesagt: Hiob 4,17-19."] },
      { number: 17, text: "\"Ich will's dir erklären, höre mir zu! / Was ich schaute, erzähle ich dir,", heading: "Ungerechten wird es schlimm ergehen" },
      { number: 18, text: "was die Weisen verkündigten, / was ihre Väter sie lehrten." },
      { number: 19, text: "Ihnen allein war das Land gegeben, / kein Fremder zog unter ihnen umher." },
      { number: 20, text: "Der Böse ängstigt sich sein Leben lang, / all die Jahre, die dem Bedrücker bestimmt sind." },
      { number: 21, text: "In seinen Ohren gellt der Schrecken, / mitten im Frieden kommt der Verwüster über ihn." },
      { number: 22, text: "Er hofft nicht mehr, dem Dunkel zu entkommen, / das Schwert des Mörders wartet schon auf ihn." },
      { number: 23, text: "Auf der Suche nach Brot irrt er umher; / er weiß, dass ein finsterer Tag auf ihn wartet." },
      { number: 24, text: "Angst und Schrecken überfallen ihn, / greifen ihn an wie ein König im Krieg." },
      { number: 25, text: "Denn gegen Gott erhebt er seine Hand, / dem Allmächtigen trotzt er." },
      { number: 26, text: "Mit den dicken Buckeln seiner Schilde / rennt er halsstarrig gegen ihn an." },
      { number: 27, text: "Denn sein Gesicht war rund und gesund, / an den Hüften hatte er Speck angesetzt," },
      { number: 28, text: "und in Städten der Geächteten hatte er Wohnung genommen, / in Häusern, die man nicht bewohnen soll, / die bestimmt waren, Trümmer zu bleiben." },
      { number: 29, text: "Er bleibt nicht reich, / sein Vermögen hat keinen Bestand, / seine Ähre* neigt sich nicht.", footnotes: ["Ähre. Die Bedeutung des hebräischen Wortes ist unbekannt. Ähre passt am besten in den Zusammenhang, weil sie sich nicht zur Erde neigt, wenn ihre Frucht nicht ausreift."] },
      { number: 30, text: "Der Finsternis entkommt er nicht, / und seinen Schössling dörrt die Flamme aus, / Gottes Atem fegt ihn weg." },
      { number: 31, text: "Warum vertraut er auf nichtige Dinge? / Er wird getäuscht, / denn er tauscht wieder Nichtiges ein." },
      { number: 32, text: "Noch vor seiner Zeit erfüllt es sich: / Sein Palmzweig grünt nicht mehr." },
      { number: 33, text: "Er ist wie ein Weinstock, der seine unreifen Trauben abstößt, / wie ein Obstbaum, der seine Blüten abwirft." },
      { number: 34, text: "Denn eine böse Sippschaft bleibt unfruchtbar, / Feuer frisst die Zelte der Bestechlichen." },
      { number: 35, text: "Mit Mühsal gehen sie schwanger und bringen Unrecht zur Welt, / ihr Schoß bringt Selbstbetrug hervor.\"" },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Da erwiderte Hiob:", heading: "Hiob weist Elifas' Rede zurück: Ihr seid leidige Tröster!" },
      { number: 2, text: "\"Ähnliches habe ich viel gehört, / ihr alle seid leidige Tröster!" },
      { number: 3, text: "Haben die windigen Worte ein Ende? / Oder was sticht dich, mir zu erwidern?" },
      { number: 4, text: "Auch ich könnte reden wie ihr, / wenn ihr an meiner Stelle wärt. / Ich könnte mit Worten gegen euch glänzen, / würde meinen Kopf über euch schütteln." },
      { number: 5, text: "Ich würde euch stärken mit meinem Mund, / der Trost von meinen Lippen würde Linderung bringen.\"" },
      { number: 6, text: "\"Wenn ich rede, hört mein Schmerz nicht auf, / lass ich es sein, geht er auch nicht fort.", heading: "Gott ist mein Feind geworden!" },
      { number: 7, text: "Ja, jetzt hat er mich erschöpft. / Du hast mein ganzes Umfeld zerstört." },
      { number: 8, text: "Und du hast mich gepackt. / Mein Verfall sagt gegen mich aus / und erhebt sich als Zeuge. / Ins Gesicht klagt er mich an." },
      { number: 9, text: "Sein Zorn zerreißt und verfolgt mich, / er knirscht mit den Zähnen / und durchbohrt mich mit seinem Blick." },
      { number: 10, text: "Sie reißen das Maul gegen mich auf, / schlagen mir voll Hohn auf die Wangen, / rotten sich zusammen gegen mich." },
      { number: 11, text: "Und Gott gibt mich den Schurken preis, / stößt mich in die Hände der Bösen." },
      { number: 12, text: "Ich war in Frieden, da verstörte er mich; / er hat mich beim Nacken gepackt und zerschmettert. / Er stellte mich als seine Zielscheibe hin," },
      { number: 13, text: "seine Pfeile umschwirren mich. / Erbarmungslos durchbohrt er meine Nieren, / schüttet meine Galle zur Erde." },
      { number: 14, text: "Bresche um Bresche schlägt er in mich; / er stürmt wie ein Krieger gegen mich an." },
      { number: 15, text: "Der Trauersack ist meine zweite Haut, / kraftlos liege ich im Staub." },
      { number: 16, text: "Mein Gesicht ist rot vom Weinen, / und meine Augen sind von dunklen Schatten umringt." },
      { number: 17, text: "Doch kein Unrecht klebt an meinen Händen, / mein Gebet ist rein.\"" },
      { number: 18, text: "\"O Erde, deck mein Blut nicht zu, / damit mein Schreien nicht zur Ruhe kommt.", heading: "Gott soll mein Richter sein!" },
      { number: 19, text: "Nun aber seht! Im Himmel ist mein Zeuge, / der in der Höhe für mich spricht." },
      { number: 20, text: "Meine Freunde sind es, die mich verspotten; / mit Tränen blickt mein Auge zu Gott." },
      { number: 21, text: "Er schaffe Recht zwischen Mensch und Gott, / zwischen dem Mann und seinem Freund." },
      { number: 22, text: "Denn die wenigen Jahre verstreichen, / dann geh ich den Weg, der ohne Wiederkehr ist.\"" },
    ] },
    { number: 17, verses: [
      { number: 1, text: "\"Mein Geist ist gebrochen, / meine Tage gelöscht, / das Grab wartet auf mich." },
      { number: 2, text: "Nichts als Spott begleitet mich, / von ihrem Gezänk kommt mein Auge nicht los." },
      { number: 3, text: "Sei du selbst mein Bürge bei dir! / Wer sonst würde die Hand für mich geben?" },
      { number: 4, text: "Ihr Herz hast du ja der Einsicht verschlossen, / darum lässt du sie nicht triumphieren." },
      { number: 5, text: "Gibt jemand seine Freunde preis, / werden die Augen seiner Kinder verdorren." },
      { number: 6, text: "Zum Spott für die Leute stellt er mich hin / als einen, dem man ins Angesicht spuckt." },
      { number: 7, text: "Mein Auge ist trüb vor Gram, / meine Glieder sind wie ein Schatten." },
      { number: 8, text: "Die Aufrechten sind darüber entsetzt, / und der Schuldlose empört sich über den Bösen." },
      { number: 9, text: "Doch der Gerechte hält fest an seinem Weg, / wer reine Hände hat, gewinnt an Kraft." },
      { number: 10, text: "Kommt alle nur wieder heran, / ich finde doch keinen Weisen bei euch.\"" },
      { number: 11, text: "\"Meine Tage sind vorbei, / zunichte meine Pläne / und was in meinem Herzen war.", heading: "Mir bleibt nur noch das Grab" },
      { number: 12, text: "Sie machen mir die Nacht zum Tag, / das Licht soll sein wie das Dunkel." },
      { number: 13, text: "Ich hoffe nichts mehr, / bei den Toten ist mein Haus, / in der Finsternis mache ich mir mein Bett." },
      { number: 14, text: "Zum Grab sage ich: 'Du bist mein Vater!'; / 'Mutter!' und 'Schwester!' zum Gewürm." },
      { number: 15, text: "Wo ist nun meine Hoffnung? / Wer kann sie denn sehen?" },
      { number: 16, text: "Sie steigt mit mir zu den Toten hinab / und sinkt mit mir in den Staub.\"" },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Da erwiderte Bildad von Schuach:", heading: "Zweite Rede des Bildad: Du zerreißt dich selbst!" },
      { number: 2, text: "\"Wie lange wollt ihr noch auf Worte lauern? / Kommt zur Besinnung, dann wollen wir reden!" },
      { number: 3, text: "Warum hält man uns für Vieh, / warum sind wir unrein vor dir?" },
      { number: 4, text: "Du zerreißt dich selbst in deinem Zorn. / Soll wegen dir die Erde veröden, / von seiner Stelle rücken ein Fels?\"" },
      { number: 5, text: "\"Doch das Licht des Gottlosen erlischt, / die Flamme seines Feuers strahlt nicht auf.", heading: "Der Gottlose bekommt seine Strafe!" },
      { number: 6, text: "Das Licht in seinem Zelt wird dunkel, / und die Leuchte über ihm erlischt." },
      { number: 7, text: "Seine starken Schritte werden kurz, / sein eigener Rat bringt ihn zu Fall." },
      { number: 8, text: "Mit eigenen Füßen gerät er ins Netz, / auf Fallgittern geht er entlang." },
      { number: 9, text: "Das Fangeisen packt seine Ferse, / die Schlinge hält ihn fest." },
      { number: 10, text: "Sein Strick ist in der Erde verborgen, / seine Falle auf dem Pfad." },
      { number: 11, text: "Ringsum überfallen ihn Schrecken / und hetzen ihn auf Schritt und Tritt." },
      { number: 12, text: "Das Unheil ist hungrig nach ihm, / das Unglück steht für ihn bereit," },
      { number: 13, text: "es frisst ihm Stücke von der Haut. / Der Vorbote des Todes frisst ihm die Glieder ab." },
      { number: 14, text: "Sein Vertrauen reißt man aus seinem Zelt, / man treibt ihn zum König der Schrecken." },
      { number: 15, text: "Keiner, der zu ihm gehört, wird in seinem Zelt wohnen, / auf seine Wohnung wird Schwefel gestreut." },
      { number: 16, text: "Unten verdorren seine Wurzeln, / und oben wird jeder Zweig dürr." },
      { number: 17, text: "Sein Andenken verschwindet im Land, / auf der Gasse kennt ihn keiner mehr." },
      { number: 18, text: "Aus dem Licht wird er ins Dunkel gestürzt, / man jagt ihn aus der Welt hinaus." },
      { number: 19, text: "Kein Kind, kein Enkel pflanzt die Sippe fort, / nicht einer überlebt in seinem Ort." },
      { number: 20, text: "Die im Westen erschaudern über seinen Tag, / und die im Osten packt das Entsetzen." },
      { number: 21, text: "Ja, das ist die Wohnung des Bösen, / die Stätte dessen, der Gott nicht kennt.\"" },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Da erwiderte Hiob:", heading: "Hiob weist Bildads Rede zurück: Ihr tut mir Unrecht!" },
      { number: 2, text: "\"Wie lange wollt ihr mich quälen, / mich mit Worten zerschlagen?" },
      { number: 3, text: "Schon zehnmal habt ihr mich beschimpft / und schämt euch nicht, mich zu misshandeln!" },
      { number: 4, text: "Und hätte ich wirklich geirrt, / müsste ich das selber ertragen." },
      { number: 5, text: "Müsst ihr denn so großtun gegen mich / und mir meine Schmach beweisen?\"" },
      { number: 6, text: "\"Seht doch ein, dass Gott mir Unrecht tut, / dass er sein Fangseil um mich zieht.", heading: "Gott behandelt mich als Feind" },
      { number: 7, text: "Ich schreie: 'Gewalt!', aber niemand hört. / Ich rufe um Hilfe, doch da ist kein Recht." },
      { number: 8, text: "Er hat mir den Weg verbaut, / ich kann nicht weiter. / Meine Pfade hüllt er mit Finsternis ein." },
      { number: 9, text: "Er zog mir meine Ehre aus / und nahm mir die Krone vom Kopf." },
      { number: 10, text: "Er hat mich ringsum niedergebrochen, so dass ich vergehe. / Meine Hoffnung riss er aus wie einen Baum." },
      { number: 11, text: "Seinen Zorn ließ er gegen mich lodern / und hat mich zu seinen Feinden gezählt." },
      { number: 12, text: "Geschlossen rückten seine Scharen an, / bahnten ihren Weg gegen mich / und lagerten sich rings um mein Zelt.\"" },
      { number: 13, text: "\"Meine Brüder hat er von mir entfernt, / Bekannte kennen mich nicht mehr.", heading: "Er hat mir Verwandte und Freunde entfremdet" },
      { number: 14, text: "Meine Verwandten halten sich fern, / meine Freunde vergessen mich." },
      { number: 15, text: "Den Gästen meines Hauses* und meinen Mägden bin ich wie ein Fremder, / ein Ausländer bin ich für sie.", footnotes: ["Gäste meines Hauses. Gemeint sind Schutzbefohlene, vielleicht Ausländer, die auf Hiobs Schutz angewiesen waren."] },
      { number: 16, text: "Ich rufe den Sklaven, er gibt keine Antwort; / ich muss ihn anflehen mit eigenem Mund." },
      { number: 17, text: "Meiner Frau ist mein Atem zuwider, / meinen Geschwistern mein Gestank." },
      { number: 18, text: "Selbst Kinder lachen über mich, / verhöhnen mich, wenn ich aufstehen will." },
      { number: 19, text: "All meine Vertrauten verabscheuen mich, / und die ich liebte, haben sich gegen mich gestellt." },
      { number: 20, text: "Nur Haut und Knochen bin ich noch, / nur das nackte Leben brachte ich davon." },
      { number: 21, text: "Habt Erbarmen, Erbarmen mit mir, meine Freunde! / Was mich zu Boden schlug, war Gottes Hand." },
      { number: 22, text: "Warum verfolgt ihr mich wie Gott, / bekommt nicht genug davon, mich zu zerfleischen?\"" },
      { number: 23, text: "\"Ich wünschte, jemand schriebe meine Worte auf, / zeichnete sie auf in ein Buch,", heading: "Ich weiß, dass mein Erlöser lebt!" },
      { number: 24, text: "mit eisernem Griffel in Blei, / in den Felsen gehauen auf ewig!" },
      { number: 25, text: "Doch ich weiß, dass mein Erlöser lebt, / er steht am Schluss über dem Tod." },
      { number: 26, text: "Nachdem man meine Haut so sehr zerschunden hat, / werde ich auch ohne mein Fleisch Gott schauen." },
      { number: 27, text: "Ihn selbst werde ich sehen, / ja, meine Augen schauen ihn an; / er wird kein Fremder für mich sein. / Ich sehne mich von Herzen danach.\"" },
      { number: 28, text: "\"Wenn ihr überlegt: 'Wie können wir ihn verfolgen, / wie finden wir den Grund seines Übels?'", heading: "Seht euch vor!" },
      { number: 29, text: "Dann fürchtet euch selbst vor dem Schwert! / Denn Zorn wird mit dem Schwert bestraft, / damit ihr wisst: Es gibt einen Richter.\"" },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Da entgegnete Zofar von Naama:", heading: "Zweite Rede des Zofar: Es drängt mich zur Antwort" },
      { number: 2, text: "\"Darauf erwidern mir meine Gedanken, / darüber denke ich nach." },
      { number: 3, text: "Ich höre, wie man mich tadelt und schmäht, / doch aus meiner Einsicht entgegnet mein Geist.\"" },
      { number: 4, text: "\"Weißt du nicht, dass immer schon, / seit es Menschen auf der Erde gibt,", heading: "Der Böse nimmt ein böses Ende" },
      { number: 5, text: "der Jubel der Gottlosen kurz ist, / die Freude der Bösen keinen Augenblick bleibt?" },
      { number: 6, text: "Reicht sein Stolz auch in den Himmel, / kommt er mit dem Kopf bis an die Wolken," },
      { number: 7, text: "wird er vergehen wie sein eigener Kot. / Die ihn sahen, fragen: 'Wo ist er?'" },
      { number: 8, text: "Wie ein Traum löst er sich unauffindbar auf, / wie ein weggescheuchtes Nachtgesicht." },
      { number: 9, text: "Das Auge sah ihn und sieht ihn nicht wieder, / seine Stätte erblickt ihn nicht mehr." },
      { number: 10, text: "Seine Kinder müssen den Armen Entschädigung zahlen, / und seine Hände den Raub erstatten." },
      { number: 11, text: "Seine Glieder waren voll Jugendkraft, / nun liegen sie mit ihm im Staub." },
      { number: 12, text: "Schmeckt das Böse in seinem Mund süß, / wenn er es unter der Zunge verbirgt," },
      { number: 13, text: "es aufspart und nicht loslassen will, / es im Gaumen zurückhält," },
      { number: 14, text: "so wird seine Speise im Leib verwandelt, / in seinem Inneren zu Natterngift." },
      { number: 15, text: "Reichtum hat er verschlungen, / nun erbricht er ihn wieder, / aus seinem Bauch treibt Gott ihn heraus." },
      { number: 16, text: "Was er sog, ist Viperngift, / die Vipernzunge tötet ihn." },
      { number: 17, text: "Er darf sich nicht an Bächen freuen, / an Strömen von Honig und Milch." },
      { number: 18, text: "Das Errungene gibt er zurück, / er darf es nicht verschlingen. / Den Reichtum, den er erwarb, / den kann er nicht genießen." },
      { number: 19, text: "Denn er knickte die Armen und ließ sie liegen, / raubte ein Haus und baute es nicht aus." },
      { number: 20, text: "Weil sein Bauch ihm keine Ruhe gab, / entkommt er mit seinen Schätzen nicht." },
      { number: 21, text: "Nichts entging seiner Fressgier, / darum hat sein Gut keinen Bestand." },
      { number: 22, text: "Trotz großem Reichtum wird ihm Angst, / die Wucht des Leidens wird über ihn kommen." },
      { number: 23, text: "Um ihm den Bauch zu füllen, / lässt Gott seine Zornglut auf ihn los, / dass sie als Brot auf ihn regnet." },
      { number: 24, text: "Flieht er vor den eisernen Waffen, / durchbohrt ihn der eherne Bogen." },
      { number: 25, text: "Zieht er sich den Pfeil aus dem Rücken, / aus der Galle die blitzende Klinge, / kommt das Grauen über ihn." },
      { number: 26, text: "Nur Finsternis ist für ihn aufgespart; / es frisst ihn ein Feuer, das niemand angeblasen hat; / es verzehrt, was übrig blieb in seinem Zelt." },
      { number: 27, text: "Der Himmel enthüllt seine Schuld, / die Erde steht gegen ihn auf." },
      { number: 28, text: "Der Wohlstand seines Hauses fährt dahin, / wenn Gottes Zorn wie eine Sturzflut kommt." },
      { number: 29, text: "So sieht das Schicksal gottloser Menschen aus, / Gott spricht ihnen dieses Erbe zu.\"" },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Da erwiderte Hiob:", heading: "Hiobs Antwort: Hört mir doch zu!" },
      { number: 2, text: "\"Hört mir doch einmal richtig zu! / Das wäre wahrer Trost von euch." },
      { number: 3, text: "Ertragt mich, dann will ich reden; / danach kannst du spotten, wenn du es willst." },
      { number: 4, text: "Richte ich meine Klage an Menschen? / Und warum sollte ich nicht ungeduldig sein?" },
      { number: 5, text: "Wendet euch zu mir und erstarrt / und legt die Hand auf den Mund!\"" },
      { number: 6, text: "\"Wenn ich daran denke, bin ich bestürzt, / und Zittern erfasst meinen Leib.", heading: "Auch Bösen geht es manchmal gut" },
      { number: 7, text: "Warum bleiben die Bösen am Leben, / werden alt und ihre Macht wächst?" },
      { number: 8, text: "Gesichert wachsen ihre Kinder auf, / und ihre Enkel haben sie um sich." },
      { number: 9, text: "Keine Furcht zerstört den Frieden ihrer Häuser, / die Rute Gottes trifft sie nicht." },
      { number: 10, text: "Sein Stier versagt nicht bei der Befruchtung, / seine Kuh kalbt ohne Fehlgeburt." },
      { number: 11, text: "Wie Schafe lassen sie ihre Knaben hinaus, / ihre Kinder tanzen und springen." },
      { number: 12, text: "Sie singen zur Handpauke und Zither, / freuen sich beim Klang der Flöte." },
      { number: 13, text: "Sie genießen ihre Tage im Glück / und fahren im Nu zu den Toten." },
      { number: 14, text: "Und doch sagen sie zu Gott: 'Bleib uns fern! / Von deinen Wegen wollen wir nichts wissen." },
      { number: 15, text: "Was sollen wir dem Allmächtigen dienen, / was nützt es uns, wenn wir ihn bitten?'" },
      { number: 16, text: "Doch das Glück steht nicht in ihrer Hand. / Vom Denken der Bösen halt ich mich fern." },
      { number: 17, text: "Wie oft erlischt die Leuchte der Bösen, / wie oft kommt Unglück über sie, / teilt er Verderben zu im Zorn!" },
      { number: 18, text: "Dann sind sie wie Stroh vor dem Wind, / wie Spreu, die der Sturmwind entführt." },
      { number: 19, text: "Spart Gott das Unheil auf für seine Kinder? / Ihm selbst vergilt er es, dass er es fühlt!" },
      { number: 20, text: "Mit eigenen Augen soll er seinen Untergang sehen / und vom Zorn des Allmächtigen trinken." },
      { number: 21, text: "Denn was schert ihn sein Haus nach ihm, / wenn die Zahl seiner Monate schwindet?\"" },
      { number: 22, text: "\"Kann man Gott Erkenntnis lehren, / ihn, der die Himmlischen richtet?", heading: "Ihr gebt trügerischen Trost" },
      { number: 23, text: "Dieser stirbt bei voller Kraft, / sorglos und in Frieden." },
      { number: 24, text: "Voller Milch sind seine Tröge, / getränkt ist das Mark seiner Knochen." },
      { number: 25, text: "Und jener stirbt im Herzen verbittert, / hat das Glück nie gekostet." },
      { number: 26, text: "Zusammen liegen sie im Staub, / und Maden decken sie zu." },
      { number: 27, text: "Seht, ich kenne eure Gedanken, / die Pläne, die ihr gegen mich macht." },
      { number: 28, text: "Ihr sagt: 'Wo ist das Haus des Edlen / und wo das Zelt, in dem die Bösen sind?'" },
      { number: 29, text: "Habt ihr nie die Reisenden gefragt, / erkennt ihr ihre Zeichen nicht?" },
      { number: 30, text: "Am Tag des Unglücks bleibt der Böse verschont, / er entgeht dem Tag des Zorns." },
      { number: 31, text: "Wer hält ihm seinen Lebenswandel vor, / wer zahlt ihm heim, was er verbrochen hat?" },
      { number: 32, text: "Doch er wird in Ehren bestattet, / man wacht bei seinem Grab." },
      { number: 33, text: "Die Erde deckt ihn freundlich zu. / Alle Welt zieht hinter ihm her / und vor ihm die zahllose Menge." },
      { number: 34, text: "Euer Trost ist nichts als Dunst, / eure Antworten bleiben Betrug.\"" },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Da erwiderte Elifas von Teman:", heading: "Dritte Runde (22-31)\nDritte Rede des Elifas: Du hältst Gott für parteiisch!" },
      { number: 2, text: "\"Kann ein Mann Gott Nutzen bringen? / Der Verständige nützt nur sich selbst." },
      { number: 3, text: "Wenn du gerecht bist, was bringt es dem Allmächtigen? / Hat er Gewinn, wenn deine Wege unschuldig sind?\"" },
      { number: 4, text: "\"Straft er dich, weil du ihn fürchtest, / geht er deshalb mit dir ins Gericht?", heading: "Gott straft dich wegen deiner Sünden!" },
      { number: 5, text: "Ist nicht deine Bosheit groß, / sind deine Sünden nicht endlos?" },
      { number: 6, text: "Du hast deinen Bruder grundlos gepfändet, / du nahmst ihm als Pfand das einzige Gewand." },
      { number: 7, text: "Dem Erschöpften hast du kein Wasser gegeben, / dem Hungrigen nicht ein Stück Brot." },
      { number: 8, text: "Dem Mann der Faust gehörte das Land, / und der Schmeichler wohnte darin." },
      { number: 9, text: "Witwen schicktest du mit leeren Händen fort, / die Arme der Waisen hast du zerschlagen." },
      { number: 10, text: "Darum sind Schlingen rings um dich her, / ein plötzlicher Schrecken macht dich bestürzt" },
      { number: 11, text: "oder Finsternis, in der du nichts siehst, / und die Wasserflut, die dich bedeckt.\"" },
      { number: 12, text: "\"Ist Gott nicht so hoch wie der Himmel? / Schau doch die höchsten Sterne an!", heading: "Hältst du Gott für unwissend?" },
      { number: 13, text: "Du aber sagst: 'Was weiß denn Gott? / Kann er durch Wolkendunkel richten?" },
      { number: 14, text: "Wolken umhüllen ihn, dass er nichts sieht, / wenn er am Himmelsgewölbe spaziert.'" },
      { number: 15, text: "Willst du den Pfad der Vorwelt befolgen, / den die Gottlosen gegangen sind," },
      { number: 16, text: "die weggerafft wurden vor der Zeit? / Wie ein Strom zerfloss ihr fester Grund." },
      { number: 17, text: "Sie sagten zu Gott: 'Mach dich fort!', / und: 'Was kann der Allmächtige uns tun?'" },
      { number: 18, text: "Hatte er doch ihre Häuser mit Gutem gefüllt. / Auch mir ist das Denken der Gottlosen fern!" },
      { number: 19, text: "Die Gerechten sehen es und freuen sich, / und der Schuldlose wird über sie spotten:" },
      { number: 20, text: "Vernichtet sind unsere Feinde! / Ihren Rest hat das Feuer gefressen.\"" },
      { number: 21, text: "\"Sei ihm doch Freund und halte Frieden! / Dadurch kommt wieder Gutes zu dir.", heading: "Ändere deine Einstellung, Hiob!" },
      { number: 22, text: "Nimm die Lehre aus seinem Mund an, / nimm dir seine Worte zu Herzen!" },
      { number: 23, text: "Wenn du zum Allmächtigen umkehrst, / wirst du wieder aufgebaut / und entfernst das Unrecht aus deinem Zelt." },
      { number: 24, text: "Wirf dein Gold doch in den Staub, / das Ofirgold* zu den Kieseln im Bach!", footnotes: ["Ofirgold. Siehe Fußnote zu 2. Chronik 8,18."] },
      { number: 25, text: "Dann ist der Allmächtige dein Gold, / das erlesene Silber für dich." },
      { number: 26, text: "Dann wirst du dich am Allmächtigen freuen / und dein Gesicht zu Gott erheben." },
      { number: 27, text: "Du wirst zu ihm beten, / und er wird dich hören. / Und du erfüllst ihm, was du gelobst." },
      { number: 28, text: "Was du beschließt, / das wird dir gelingen. / Auf deinen Wegen wird es hell." },
      { number: 29, text: "Gott erniedrigt, die hochmütig reden, / doch wer die Augen niederschlägt, dem hilft er." },
      { number: 30, text: "Er rettet selbst den, der nicht schuldlos ist; / durch die Reinheit deiner Hände wird er befreit.\"" },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Hiob erwiderte:", heading: "Hiobs Antwort: Wenn ich Gott nur finden könnte!" },
      { number: 2, text: "\"Auch heute lehnt sich meine Klage auf, / meine Hand muss mein Stöhnen bezwingen." },
      { number: 3, text: "Wüsste ich nur, wie ich ihn finden, / zu ihm hingelangen könnte." },
      { number: 4, text: "Ich würde ihm meinen Rechtsfall erläutern, / meinen Mund mit Beweisgründen füllen." },
      { number: 5, text: "Ich würde wissen, was er mir erwidert, / erfahren, was er zu mir sagt." },
      { number: 6, text: "Würde er in seiner Allmacht mit mir streiten? / Nein, gerade er wird auf mich achten." },
      { number: 7, text: "Ein Aufrechter würde dort mit ihm streiten, / und ich hätte mein Recht für immer gesichert.\"" },
      { number: 8, text: "Geh ich nach Osten, ist er nicht da, / und nach Westen, bemerk ich ihn nicht." },
      { number: 9, text: "Wirkt er im Norden, kann ich ihn nicht sehen, / und im Süden, da erblicke ich ihn nicht." },
      { number: 10, text: "Er kennt doch meinen Weg. / Wenn er mich prüfte, wäre ich wie Gold." },
      { number: 11, text: "Mein Fuß blieb in seiner Spur; / ich blieb auf seinem Weg und wich nicht ab." },
      { number: 12, text: "Ich ließ nicht ab von dem, was er mir gebot, / wich nicht von meinem Vorsatz ab / und verwahrte die Worte aus seinem Mund." },
      { number: 13, text: "Doch er ist der Eine. / Wer kann ihm wehren? / Was er will, das tut er auch." },
      { number: 14, text: "Er vollendet, was er mir bestimmt hat, / und hält davon noch mehr bereit." },
      { number: 15, text: "Darum bin ich so bestürzt vor ihm, / ich denke daran und habe vor ihm Angst." },
      { number: 16, text: "Gott hat mein Herz verzagt gemacht, / der Allmächtige macht mich bestürzt." },
      { number: 17, text: "Denn nicht wegen Finsternis vergehe ich / und auch nicht, weil mich Dunkelheit bedeckt.\"" },
    ] },
    { number: 24, verses: [
      { number: 1, text: "\"Warum setzt der Allmächtige keine Gerichtstage fest? / Warum sehen die, die ihn kennen, seine Gerechtigkeit* nicht?", heading: "Die Gottlosen haben Erfolg!", footnotes: ["Gerechtigkeit. Wörtlich: Tage. Gemeint sind die Tage, an denen er Gericht hält."] },
      { number: 2, text: "Sie verrücken die Grenzen, / rauben die Herde und lassen sie weiden." },
      { number: 3, text: "Sie treiben den Esel der Waisen weg / und nehmen das Rind der Witwe zum Pfand." },
      { number: 4, text: "Sie stoßen die Bedürftigen vom Weg. / Die Armen des Landes verkriechen sich alle." },
      { number: 5, text: "Wie Wildesel in der Wüste / müssen sie ans Tagewerk gehen / und suchen schon früh nach Nahrung. / Die Steppe gibt ihnen Brot für die Kinder." },
      { number: 6, text: "Auf freiem Feld schneiden sie Futterkorn ab, / suchen Beeren im Weinberg des Bösen." },
      { number: 7, text: "Nackt übernachten sie ohne Gewand / und haben keine Decke im Frost." },
      { number: 8, text: "Vom Regen der Berge sind sie durchnässt, / an den Felsen suchen sie Schutz." },
      { number: 9, text: "Der Witwe reißt man ihren Säugling weg; / die Waise des Armen nimmt man zum Pfand." },
      { number: 10, text: "Nackt müssen sie gehen, ohne Gewand, / und hungernd schleppen sie Garben." },
      { number: 11, text: "In deren Hainen pressen sie das Öl, / treten die Kelter und haben doch Durst." },
      { number: 12, text: "In der Stadt hört man Sterbende ächzen, / Verletzte schreien um Hilfe, / doch Gott nimmt keinen Anstoß daran." },
      { number: 13, text: "Jene sind Feinde des Lichts / und wissen nichts von Gottes Wegen. / Sie bleiben auch nicht auf seinem Pfad." },
      { number: 14, text: "Noch vor dem Taglicht steht der Mörder auf, / um den Elenden und Armen zu töten. / Und der Dieb geht um in der Nacht." },
      { number: 15, text: "Der Ehebrecher wartet auf die Dämmerung; / er sagt: 'Kein Auge soll mich sehen!', / und er verhüllt sein Gesicht." },
      { number: 16, text: "Im Dunkeln brechen sie ein in die Häuser. / Am Tag, da verstecken sie sich, / denn sie scheuen das Licht." },
      { number: 17, text: "Die Finsternis gilt ihnen als Morgen, / mit ihrem Schrecken sind sie wohlvertraut.\"" },
      { number: 18, text: "\"Schnell fahren sie dahin wie auf Wasser, / verflucht ist ihr Los auf der Erde. / Den Weg zu den Weinbergen gehen sie nicht mehr.", heading: "Erst in der Ewigkeit werden sie bestraft!" },
      { number: 19, text: "Dürre und Hitze raffen Schneewasser weg, / so schluckt die Totenwelt einen Sünder." },
      { number: 20, text: "Selbst der Mutterleib vergisst ihn. / An ihm labt sich das Gewürm. / Nie mehr wird an ihn gedacht. / So zerbricht das Böse wie ein Baum." },
      { number: 21, text: "So auch der, der die Kinderlose beraubte / und der Witwe keine Freundlichkeit erwies." },
      { number: 22, text: "Starke reißt Gott durch seine Kraft um. / Steht er auf, sind sie des Lebens nicht sicher." },
      { number: 23, text: "Er wiegt sie nur in Sicherheit, / doch seine Augen sind auf ihren Wegen." },
      { number: 24, text: "Sie kommen für kurze Zeit hoch, / doch dann ist es aus; / sie sinken hin, / man rafft sie wie alle anderen weg; / sie verwelken wie die Spitze der Ähre." },
      { number: 25, text: "Ist es nicht so? / Wer will mich Lügen strafen? / Wer kann meine Worte widerlegen?\"" },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Da erwiderte Bildad von Schuach:", heading: "Dritte Rede des Bildad: Kein Mensch ist gerecht vor Gott!" },
      { number: 2, text: "\"Herrschaft und Schrecken ist bei ihm, / der Frieden schafft in seinen Höhen." },
      { number: 3, text: "Kann man seine Scharen zählen? / Über wem geht sein Licht nicht auf?" },
      { number: 4, text: "Wie will der Mensch gerecht sein vor Gott, / wie rein der von einer Frau Geborene?" },
      { number: 5, text: "Schau, nicht einmal der Mond ist vor ihm hell, / und die Sterne sind in seinen Augen nicht rein," },
      { number: 6, text: "wie viel weniger der Mensch, diese Made, / das Menschenkind, der kleine Wurm!\"" },
    ] },
    { number: 26, verses: [
      { number: 1, text: "Hiob erwiderte:", heading: "Hiobs Antwort: Du hast nur leere Worte." },
      { number: 2, text: "\"Wie hilfst du doch der Schwachheit auf / und stehst der Ohnmacht bei!" },
      { number: 3, text: "Wie gut du Dummheit berätst / und großes Wissen offenbarst!" },
      { number: 4, text: "Wessen Reden hast du vermeldet, / und wessen Geist ging von dir aus?\"" },
      { number: 5, text: "\"Es beben die Schatten dort unten, / das Wasser und die darin wohnen.", heading: "Ich zeige dir die Größe Gottes" },
      { number: 6, text: "Das Grab ist nackt vor ihm, / der Abgrund hat keine Decke." },
      { number: 7, text: "Er spannt den Norden aus über der Leere, / hängt die Erde auf über dem Nichts." },
      { number: 8, text: "Er bindet das Wasser in seine Wolken, / und das Gewölk zerreißt darunter nicht." },
      { number: 9, text: "Er versperrt den Anblick seines Thrones / und breitet sein Gewölk davor aus." },
      { number: 10, text: "Er zieht eine Grenze über dem Wasser / wo Finsternis und Licht sich scheiden." },
      { number: 11, text: "Die Säulen des Himmels wanken, / erstarren, wenn Gott sie bedroht." },
      { number: 12, text: "Durch seine Kraft erregt er das Meer, / durch seine Einsicht zerschmettert er das Ungetüm*.", footnotes: ["Ungetüm. Wörtlich: Rahab, siehe Fußnote zu Hiob 9,13."] },
      { number: 13, text: "Der Himmel wird heiter durch seinen Hauch, / seine Hand durchbohrt die flüchtige Schlange*.", footnotes: ["Die flüchtige Schlange ist offenbar ein anderer Begriff für das Ungetüm, das in Kapitel 40 und 41 Leviatan genannt und ausführlich beschrieben wird."] },
      { number: 14, text: "Das sind nur kleine Fingerzeige von dem, was er tut; / wir vernehmen ja nur ein Wispern von ihm. / Wer könnte denn den Donner seiner Macht verstehen?\"" },
    ] },
    { number: 27, verses: [
      { number: 1, text: "Hiob setzte seine Rede fort, er sagte:", heading: "Hiobs Schlussrede: Ich gebe euch nicht recht!" },
      { number: 2, text: "\"So wahr Gott lebt, der mir mein Recht entzog, / der Allmächtige, der mir das Leben bitter macht:" },
      { number: 3, text: "Solange noch mein Atem in mir ist, / in meiner Nase Gottes Hauch," },
      { number: 4, text: "kommt kein Unrecht über meine Lippen, / werde ich niemals die Unwahrheit sagen." },
      { number: 5, text: "Ich denke nicht daran, euch recht zu geben. / Bis in den Tod gebe ich meine Unschuld nicht preis." },
      { number: 6, text: "An meiner Gerechtigkeit halte ich fest und lasse sie nicht; / keinen meiner Tage hält mein Gewissen mir vor.\"" },
      { number: 7, text: "\"Meinem Feind soll es wie dem Gottlosen gehen, / dem, der gegen mich steht, wie einem Verbrecher.", heading: "Mein Feind sei wie der Gottlose!" },
      { number: 8, text: "Denn was ist die Hoffnung des Gewissenlosen, / wenn Gott ihm seine Seele nimmt?" },
      { number: 9, text: "Wird Gott sein Schreien hören, / wenn die Not ihn überfällt?" },
      { number: 10, text: "Wird er sich am Allmächtigen freuen, / kann er ihn jederzeit rufen?\"" },
      { number: 11, text: "\"Ich will euch belehren über Gottes Tun, / nicht verhehlen, was der Allmächtige plant.", heading: "Gottlose werden untergehen!" },
      { number: 12, text: "Ihr alle habt es selbst geschaut, / warum schwatzt ihr so nichtiges Zeug?" },
      { number: 13, text: "Das ist das Los des gottlosen Menschen bei Gott, / das Erbe des Tyrannen, das er vom Allmächtigen bekommt:" },
      { number: 14, text: "Wenn seine Kinder sich mehren, dann für das Schwert; / und seine Sprösslinge haben nicht genug Brot." },
      { number: 15, text: "Die ihm bleiben, begräbt die Pest; / und seine Witwen weinen nicht." },
      { number: 16, text: "Wenn er auch Silber wie Staub anhäuft / und Kleidung stapelt in Massen," },
      { number: 17, text: "dann häuft er sie auf, doch der Gerechte zieht sie an / und das Silber nimmt ein Schuldloser mit." },
      { number: 18, text: "Wie eine Motte baut er sein Haus, / wie eine Hütte, die der Wächter aufstellt." },
      { number: 19, text: "Reich legt er sich hin / und tut es nicht wieder, / er schlägt die Augen auf / und ist nicht mehr." },
      { number: 20, text: "Wie eine Flut holt ihn der Schrecken ein, / nachts entführt ihn ein Sturm." },
      { number: 21, text: "Der Ostwind hebt ihn hoch und reißt ihn mit, / er fegt ihn von seiner Wohnstätte weg." },
      { number: 22, text: "Schonungslos wirft er sich auf ihn, / er flieht und flieht vor seiner Macht." },
      { number: 23, text: "Man klatscht über ihn in die Hände, / man zischt ihm von seiner Stätte aus nach.\"" },
    ] },
    { number: 28, verses: [
      { number: 1, text: "\"Das Silber hat seinen Fundort, / das Gold eine Stätte, wo man es wäscht.", heading: "Weisheit nur durch Gottesfurcht" },
      { number: 2, text: "Eisen holt man aus der Erde, / Kupfer schmilzt man aus Gestein." },
      { number: 3, text: "Man setzt der Finsternis ein Ende; / bis in die letzten Winkel stößt man vor; / aus tiefem Dunkel holt man das Gestein." },
      { number: 4, text: "Man teuft* einen Schacht von da aus, wo man wohnt. / Und dort, wo kein Wanderer vorüberzieht, / baumeln und schweben sie fern von den Menschen.", footnotes: ["Teufen ist ein Wort aus der Bergmannssprache und bezeichnet die Herstellung von senkrechten Hohlräumen in der Erde zum Abbau von Bodenschätzen, wozu die Bergleute damals hinabgelassen wurden."] },
      { number: 5, text: "Oben auf der Erde sprosst das Getreide, / und unten wird sie wie von Feuer zerwühlt." },
      { number: 6, text: "Ihre Steine bergen den Saphir, / auch Goldstaub findet sich dort." },
      { number: 7, text: "Kein Adler kennt diesen Pfad, / kein Habicht hat ihn je erblickt;" },
      { number: 8, text: "nie betrat ihn ein wildes Tier, / kein Löwe ging je dort entlang." },
      { number: 9, text: "An harten Stein hat man die Hand gelegt, / vom Fuß der Berge aus wühlt man sie um" },
      { number: 10, text: "und treibt Stollen in die Felsen vor. / Kostbares hat das Auge erblickt." },
      { number: 11, text: "Die Wasseradern hat man eingedämmt. / Verborgenes zieht man ans Licht." },
      { number: 12, text: "Aber die Weisheit, wo findet man sie? / Wo ist der Ort des Verstandes?" },
      { number: 13, text: "Kein Mensch kennt die Stelle, wo sie ist, / und im Land der Lebenden findet man sie nicht." },
      { number: 14, text: "Die Tiefe sagt: 'Sie ist nicht hier!', / und das Meer: 'Auch nicht bei mir.'" },
      { number: 15, text: "Sie wird mit keinem Geld gekauft / und nicht mit Silber aufgewogen." },
      { number: 16, text: "Man kann sie nicht mit Ofirgold bezahlen, / mit kostbarem Onyx und Saphir." },
      { number: 17, text: "Gold und Glas haben nicht ihren Wert, / man kann sie nicht gegen Goldschmuck eintauschen," },
      { number: 18, text: "ganz zu schweigen von Korallen und Kristall. / Wer Weisheit hat, hat mehr als Perlen." },
      { number: 19, text: "Der Topas aus Nubien kommt ihr nicht gleich, / reines Gold wiegt sie nicht auf." },
      { number: 20, text: "Die Weisheit – wo kommt sie nur her? / Wo ist der Ort des Verstandes?" },
      { number: 21, text: "Dem menschlichen Auge ist sie verborgen, / auch die Vögel erspähen sie nicht." },
      { number: 22, text: "Selbst Abgrund und Tod müssen bekennen: / 'Wir haben bloß von ihr reden gehört.'" },
      { number: 23, text: "Nur Gott versteht ihren Weg, / nur er kennt ihre Stätte." },
      { number: 24, text: "Denn er blickt bis zu den Enden der Erde, / sieht alles auf der ganzen Welt." },
      { number: 25, text: "Als er dem Wind sein Gewicht gab, / als er das Maß des Wassers bestimmte," },
      { number: 26, text: "als er das Gesetz des Regens verfügte / und die Bahn für den Donnerstrahl," },
      { number: 27, text: "da sah er sie und hat sie ermessen, / er setzte sie ein und ergründete sie." },
      { number: 28, text: "Und den Menschen sagte er: / 'Seht, Jahwe zu fürchten ist Weisheit, / und Böses zu meiden, Verstand!'\"" },
    ] },
    { number: 29, verses: [
      { number: 1, text: "Hiob setzte seine Rede fort und sagte:", heading: "Hiobs vergangenes Glück" },
      { number: 2, text: "\"Ach wäre ich doch wie in den früheren Jahren, / wie in den Tagen, als Gott mich beschützte," },
      { number: 3, text: "als seine Leuchte über mir schien, / als ich in seinem Licht durchs Dunkel ging;" },
      { number: 4, text: "wie ich war in der Zeit meiner Reife, / als Gottes Freundschaft über meinem Zelt stand," },
      { number: 5, text: "als der Allmächtige noch mit mir war / und meine Söhne mich umgaben;" },
      { number: 6, text: "als ich meine Füße in Sahne badete, / der Fels neben mir Ölbäche ergoss!" },
      { number: 7, text: "Ging ich durchs Tor zur Stadt hinauf / und stellte meinen Sitz auf den Platz," },
      { number: 8, text: "traten die Jungen beiseite, wenn sie mich sahen; / die Alten erhoben sich, blieben stehen," },
      { number: 9, text: "die Fürsten hielten ihr Reden zurück / und legten die Hand auf den Mund." },
      { number: 10, text: "Die Stimme der Vornehmen verstummte, / ihnen klebte die Zunge am Gaumen." },
      { number: 11, text: "Hörte mich jemand, so pries er mich glücklich; / sah mich einer, so bezeugte er mir," },
      { number: 12, text: "dass ich den Elenden rettete, der um Hilfe schrie, / und die Waise, die ohne Beistand war." },
      { number: 13, text: "Der Segen des Verlorenen kam über mich, / das Herz der Witwe machte ich jubeln." },
      { number: 14, text: "Ich kleidete mich in Gerechtigkeit, / das Recht war mir Mantel und Kopfbund." },
      { number: 15, text: "Für den Blinden war ich Auge / und für den Lahmen Fuß." },
      { number: 16, text: "Für die Armen war ich ein Vater / und erforschte den Streit mir Unbekannter." },
      { number: 17, text: "Ich zerbrach den Kiefer des Bösen, / entriss seinen Zähnen die Beute." },
      { number: 18, text: "So dachte ich: 'In meinem Nest werde ich sterben / und meine Tage mehren wie Sand.'" },
      { number: 19, text: "Meine Wurzel war offen zum Wasser, / auf meinen Zweigen ruhte der Tau." },
      { number: 20, text: "Meine Ehre blieb immer frisch, / und mein Bogen wurde in meiner Hand stärker." },
      { number: 21, text: "Sie hörten auf mich und warteten / und lauschten schweigend meinem Rat." },
      { number: 22, text: "Nach meinem Wort sprachen sie nicht, / meine Rede träufelte auf sie." },
      { number: 23, text: "Sie warteten auf mich wie auf Regen, / sperrten den Mund wie nach Spätregen auf." },
      { number: 24, text: "Ich lachte ihnen zu, wenn sie kein Zutrauen hatten, / mein strahlendes Gesicht trübten sie nicht." },
      { number: 25, text: "Ich wählte für sie den Weg aus und saß da als Haupt; / ich thronte wie ein König in seinen Scharen, / wie einer, der Trauernde tröstet.\"" },
    ] },
    { number: 30, verses: [
      { number: 1, text: "\"Jetzt aber lachen über mich, / die jünger sind als ich. / Deren Väter hätte ich nicht / zu den Hunden meiner Herde gestellt.", heading: "Hiobs gegenwärtiges Leid" },
      { number: 2, text: "Was sollte mir ihre Hilfe, / wenn ihnen jede Kraft fehlt?" },
      { number: 3, text: "Durch Mangel und Hunger abgezehrt / nagen sie die Steppe ab, / die längst öde und kahl ist." },
      { number: 4, text: "Sie pflücken Salzkraut beim Gesträuch, / Ginsterwurzel ist ihr Brot." },
      { number: 5, text: "Aus der Gemeinschaft werden sie vertrieben, / man schreit über sie wie über den Dieb." },
      { number: 6, text: "Sie hausen in grausigen Schluchten, / in Löchern und Klüften der Erde." },
      { number: 7, text: "Zwischen den Büschen kreischen sie, / und unter Dornen sammeln sie sich." },
      { number: 8, text: "Kinder von namenlosem Gesindel, / die man mit Peitschen aus dem Land trieb." },
      { number: 9, text: "Und jetzt bin ich ihr Spottlied, / bin ihnen zum Gerede geworden." },
      { number: 10, text: "Sie verabscheuen mich, rücken von mir ab / und spucken mir voll ins Gesicht." },
      { number: 11, text: "Gott hat mich schwach und wehrlos gemacht, / so lassen sie ihre Hemmungen fahren." },
      { number: 12, text: "Zur Rechten erhebt sich die Brut; / sie stoßen meine Füße weg / und bahnen einen Weg, mich zu verderben." },
      { number: 13, text: "Sie zerstören meinen Pfad, / sie schüren mein Verderben, / und niemand muss ihnen helfen." },
      { number: 14, text: "Sie kommen wie durch eine Bresche, / wälzen sich unter Trümmern heran." },
      { number: 15, text: "Schrecken hat sich gegen mich gekehrt, / verfolgt wie der Wind meine Würde, / und mein Heil zieht weg wie eine Wolke." },
      { number: 16, text: "Und nun zerfließt die Seele in mir, / Tage des Elends halten mich fest." },
      { number: 17, text: "Die Nacht durchbohrt mein Gebein, / die nagenden Schmerzen hören nicht auf." },
      { number: 18, text: "Durch ihre große Heftigkeit / entstellt sich mein Gewand / und schnürt mich ein wie ein Hemd." },
      { number: 19, text: "Er hat mich in den Dreck gestürzt, / wie Staub und Asche bin ich geworden." },
      { number: 20, text: "Ich schreie zu dir, und du antwortest nicht; / ich stehe da, und du starrst mich nur an." },
      { number: 21, text: "Zum Grausamen wandelst du dich, / mit starker Hand verfolgst du mich." },
      { number: 22, text: "Du hebst mich hoch, lässt mich reiten im Wind, / dass ich die Besinnung verlier." },
      { number: 23, text: "Ich weiß, du führst mich in den Tod, / ins Haus, wo alles Lebendige sich sammelt." },
      { number: 24, text: "Doch streckt man beim Sturz nicht die Hand aus, / schreit man nicht beim Untergang?" },
      { number: 25, text: "Weinte ich denn nicht über den, der harte Tage hatte? / Hatte ich mit Armen denn kein Mitgefühl?" },
      { number: 26, text: "So erwartete ich Gutes, doch es kam Böses; / ich wartete auf Licht, doch es kam Finsternis." },
      { number: 27, text: "Mein Inneres ist aufgewühlt, kommt nicht zur Ruhe; / mich haben die Tage des Elends erreicht." },
      { number: 28, text: "Ich geh ohne Sonne in Trauer, / ich steh in der Versammlung auf und schreie." },
      { number: 29, text: "Den Schakalen bin ich ein Bruder geworden, / ein Gefährte der Strauße." },
      { number: 30, text: "Meine Haut ist schwarz und löst sich ab, / meine Knochen glühen von Fieber." },
      { number: 31, text: "Meine Zither klagt, / und meine Flöte weint.\"" },
    ] },
    { number: 31, verses: [
      { number: 1, text: "\"Ich hatte einen Bund mit meinen Augen geschlossen. / Wie sollte ich da lüstern auf Jungfrauen blicken?", heading: "Hiob hält an seiner Unschuld fest" },
      { number: 2, text: "Was wäre sonst mein Teil von Gott dort oben, / das Erbe vom Allmächtigen aus der Höhe?" },
      { number: 3, text: "Wird den Ungerechten nicht Verderben treffen, / Missgeschick den Bösen?" },
      { number: 4, text: "Sieht er nicht meine Wege / und zählt all meine Schritte?" },
      { number: 5, text: "Bin ich je mit der Lüge gegangen, / eilte mein Fuß zum Betrug?" },
      { number: 6, text: "Gott soll mich auf der Waage der Gerechtigkeit wiegen, / dann wird er meine Unschuld erkennen." },
      { number: 7, text: "Ist mein Schritt vom Weg abgebogen, / mein Herz meinen Augen gefolgt, / klebt ein Makel an meiner Hand:" },
      { number: 8, text: "dann esse ein anderer, was ich säe, / dann werde meine Ernte vernichtet." },
      { number: 9, text: "Hat sich mein Herz zur Frau locken lassen, / habe ich an der Tür meines Nächsten gelauert:" },
      { number: 10, text: "dann soll meine Frau für einen anderen kochen*, / dann sollen andere schlafen mit ihr.", footnotes: ["kochen. Wörtlich: (Getreide) mahlen, d.h. eine Mahlzeit vorbereiten."] },
      { number: 11, text: "Denn das wäre eine Schandtat, / eine Schuld, die vor die Richter gehört." },
      { number: 12, text: "Das wäre ein Feuer, das bis zum Untergang frisst, / es entwurzelt meinen ganzen Ertrag." },
      { number: 13, text: "Habe ich meinem Sklaven das Recht versagt / und meiner Sklavin, wenn sie gegen mich klagten?" },
      { number: 14, text: "Was wollte ich tun, wenn Gott sich erhebt, / was ihm entgegnen, wenn er es untersucht?" },
      { number: 15, text: "Hat nicht einer uns beide im Schoß gebildet, / nicht einer im Leib uns gemacht?" },
      { number: 16, text: "Habe ich jemals den Armen einen Wunsch versagt, / ließ ich die Augen der Witwe erlöschen?" },
      { number: 17, text: "Habe ich meinen Bissen allein gegessen, / dass das Waisenkind nichts davon abbekam?" },
      { number: 18, text: "Von Jugend an zog Gott mich wie ein Vater groß, / und von Mutterliebe gelehrt habe ich die Waise geführt." },
      { number: 19, text: "Habe ich jemand umkommen sehen, weil er nichts anhatte; / ließ ich einen Armen ohne Decke gehn?" },
      { number: 20, text: "Die Wolle meiner Schafe wärmte ihn, / und er hat mich dafür gesegnet." },
      { number: 21, text: "Habe ich Elternlose bedroht, / weil ich Helfer im Tor hatte:" },
      { number: 22, text: "dann soll die Schulter mir vom Nacken fallen / und mein Arm abbrechen vom Gelenk!" },
      { number: 23, text: "Die Furcht vor Gottes Strafe schreckte mich ab, / vor seiner Hoheit bestünde ich nicht." },
      { number: 24, text: "Habe ich mein Vertrauen auf Gold gesetzt, / das Feingold meine Zuversicht genannt?" },
      { number: 25, text: "Habe ich mich gefreut, dass mein Vermögen riesig war, / dass meine Hand Gewaltiges schaffte?" },
      { number: 26, text: "Habe ich gesehen, wie hell die Sonne leuchtet, / wie der Mond so prächtig dahinzieht," },
      { number: 27, text: "und hat mein Herz mich im Stillen verführt, / sie mit Kusshand zu verehren:" },
      { number: 28, text: "dann wäre das eine Schuld, die vor die Richter gehört, / dann hätte ich Gott in der Höhe verleugnet." },
      { number: 29, text: "Freute ich mich über das Scheitern meines Hassers, / ergötzte es mich, als Böses ihn traf?" },
      { number: 30, text: "Nein, ich erlaubte meinem Mund nicht die Sünde, / mit einem Fluch sein Leben zu fordern." },
      { number: 31, text: "Haben nicht meine Zeltgenossen gesagt: / 'Wer wurde von seinem Braten nicht satt?'" },
      { number: 32, text: "Der Gast blieb nicht über Nacht draußen, / meine Tür tat ich dem Wanderer auf." },
      { number: 33, text: "Habe ich wie Adam meine Sünde verdeckt, / meine Schuld in meiner Brust versteckt," },
      { number: 34, text: "weil ich die große Menge scheute, / die Verachtung der Sippe mich schreckte, / so dass ich schwieg und nicht zur Tür hinausging?" },
      { number: 35, text: "Ach, hätte ich doch einen, der auf mich hört! / Hier ist meine Unterschrift! / Der Allmächtige antworte mir! / Hätte ich die Klageschrift meines Gegners," },
      { number: 36, text: "auf meine Schulter wollt' ich sie legen, / mir umbinden wie eine Krone!" },
      { number: 37, text: "Jeden meiner Schritte würde ich ihm offen legen, / ihm nahen wie ein Fürst." },
      { number: 38, text: "Klagte mein Acker über mich, / weinten alle seine Furchen?" },
      { number: 39, text: "Hab' ich seine Frucht unbezahlt verzehrt, / seinen Besitzer umkommen lassen?" },
      { number: 40, text: "Dann sollen Dornen wachsen statt Weizen, / Unkraut anstelle von Gerste!\"Die Worte Hiobs sind zu Ende." },
    ] },
    { number: 32, verses: [
      { number: 1, text: "Nun hörten die drei Männer auf, Hiob zu antworten, denn er hielt sich selbst für gerecht.", heading: "32-37: Die Reden Elihus\nWarum Elihu eingreift (32)\nDie Reden Elihus: Zorn über fruchtloses Gerede" },
      { number: 2, text: "Da flammte der Zorn Elihus auf. Elihu war ein Sohn Barachels von Bus* aus der Sippe Ram. Sein Zorn richtete sich gegen Hiob, weil er sich selbst mehr rechtfertigte als Gott.", footnotes: ["Bus. Nach 1. Mose 22,21 war Bus ein Sohn von Nahor, dem Bruder Abrahams. Sein Bruder hieß Uz wie das Land, in dem Hiob wohnte."] },
      { number: 3, text: "Gegen dessen drei Freunde richtete sich sein Zorn, weil sie keine Antwort fanden und Hiob doch verdammten." },
      { number: 4, text: "Elihu hatte sich Hiob gegenüber mit seinen Worten zurückgehalten, weil jene älter waren als er." },
      { number: 5, text: "Dann aber sah er, dass die drei Männer keine Antwort mehr wussten. Da entflammte sein Zorn." },
      { number: 6, text: "Elihu, der Sohn Barachels von Bus, ergriff das Wort und sagte:\"Noch bin ich jung an Jahren, / doch ihr seid hochbetagt. / Darum hielt ich mich zurück und scheute mich, / euch mein Wissen kundzutun.", heading: "Der Grund für sein Eingreifen" },
      { number: 7, text: "Ich dachte: 'Lass das Alter reden, / lass die Ergrauten Weisheit verkünden.'" },
      { number: 8, text: "Doch es ist der Geist im Menschen, / der Hauch des Allmächtigen, der sie verständig macht." },
      { number: 9, text: "Nicht die Großen sind weise, / noch verstehen die Alten, was recht ist." },
      { number: 10, text: "Darum sage ich: 'Hört mir zu! / Auch ich will mein Wissen verkünden.'" },
      { number: 11, text: "Ich habe auf eure Reden gewartet, / auf eure klugen Sprüche gehört, / bis ihr die Worte getroffen hättet." },
      { number: 12, text: "Ich bin euch aufmerksam gefolgt, / doch keiner hat Hiob widerlegt, / seine Reden beantwortet." },
      { number: 13, text: "Sagt nicht: 'Wir haben die Weisheit gefunden, / Gott muss ihn schlagen – und nicht ein Mensch.'" },
      { number: 14, text: "Nicht gegen mich hat er seine Worte gerichtet, / und mit euren Sprüchen antworte ich nicht." },
      { number: 15, text: "Sie sind bestürzt, sie antworten nicht, / es fehlen ihnen die Worte." },
      { number: 16, text: "Ich habe gewartet, doch sie reden nicht, / sie stehen da, sagen nichts mehr." },
      { number: 17, text: "Auch ich will mein Teil zur Antwort geben, / auch ich will mein Wissen verkünden." },
      { number: 18, text: "Denn mit Worten bin ich randvoll angefüllt, / mich drängt der Geist, der in mir ist." },
      { number: 19, text: "Mein Inneres ist wie junger Wein, der eingeschlossen ist, / will wie neugefüllte Schläuche bersten." },
      { number: 20, text: "Ich will reden, damit mir leichter wird, / die Lippen öffnen und erwidern." },
      { number: 21, text: "Ich werde für niemand Partei ergreifen, / keinem Menschen werde ich schmeicheln." },
      { number: 22, text: "Nein, denn schmeicheln kann ich nicht, / sonst rafft mich mein Schöpfer bald weg.\"" },
    ] },
    { number: 33, verses: [
      { number: 1, text: "\"So hör auf meine Rede, Hiob, / nimm meine Worte zu Ohren.", heading: "Drei Antworten auf drei Gesprächsrunden (33-35)\nElihus erste Rede: Aufruf an Hiob" },
      { number: 2, text: "Sieh doch, ich habe meinen Mund geöffnet, / die Worte liegen mir auf der Zunge." },
      { number: 3, text: "Ich rede mit aufrichtigem Herzen, / meine Lippen bringen klares Wissen vor." },
      { number: 4, text: "Gottes Geist hat mich gemacht, / der Hauch des Allmächtigen belebt mich." },
      { number: 5, text: "Wenn du kannst, so antworte mir, / leg es mir vor und stell dich!" },
      { number: 6, text: "Schau, vor Gott bin ich wie du, / vom Ton geknetet bin auch ich." },
      { number: 7, text: "Furcht vor mir muss dich nicht schrecken, / ich setze dich nicht unter Druck.\"" },
      { number: 8, text: "\"Du sagtest doch vor meinen Ohren, / und den Laut deiner Worte höre ich noch:", heading: "Zurückweisung der Worte Hiobs" },
      { number: 9, text: "'Ich bin rein, ohne Vergehen, / makellos und frei von Schuld." },
      { number: 10, text: "Doch er fand eine Sache gegen mich, / er hält mich für seinen Feind." },
      { number: 11, text: "Er legt meine Füße in den Block, / überwacht jeden meiner Wege.'" },
      { number: 12, text: "Da liegst du falsch, / entgegne ich dir, / denn Gott ist mehr als ein Mensch." },
      { number: 13, text: "Was haderst du mit ihm? / Er gibt keine Antwort über sein Tun.\"" },
      { number: 14, text: "\"Doch in einer Weise redet Gott, / und in zweien, / und man achtet nicht darauf.", heading: "Gott redet auf zwei Arten mit uns" },
      { number: 15, text: "Im Traum, im Nachtgesicht, / wenn Schlaf die Menschen überfällt, / im Schlummer auf dem Lager." },
      { number: 16, text: "Dann öffnet er dem Menschen das Ohr / und bestätigt die Warnung für ihn," },
      { number: 17, text: "um den Menschen von seinem Tun abzubringen, / den Hochmut auszutreiben vom Mann." },
      { number: 18, text: "Er will ihn vor dem Grab bewahren, / sein Leben vom Lauf in den Tod." },
      { number: 19, text: "Er wird gemahnt durch Schmerz auf dem Lager, / den er in allen seinen Gliedern fühlt." },
      { number: 20, text: "Dann ist ihm selbst das Essen zuwider, / die Lieblingsspeise mag er nicht mehr." },
      { number: 21, text: "Er magert ab bis auf die Knochen; / sie stehen vor, wo man sie früher nicht sah." },
      { number: 22, text: "Sein Leben nähert sich dem Grab, / seine Seele den Mächten des Todes." },
      { number: 23, text: "Ist dann ein Bote für ihn da, / ein Mittler, einer von tausend, / der dem Menschen das Rechte erklärt," },
      { number: 24, text: "so ist er ihm gnädig und spricht: / 'Lass ihn nicht ins Grab hinuntergehen, / ich fand das Lösegeld für ihn.'" },
      { number: 25, text: "Dann wird sein Körper wieder frisch und stark, / er kehrt in die Zeit seiner Jugend zurück." },
      { number: 26, text: "Dann fleht er zu Gott, und dieser nimmt ihn gnädig an; / er darf sein Angesicht mit Jubel schauen, / und dieser gibt dem Menschen seine Gerechtigkeit wieder." },
      { number: 27, text: "Er wird vor den Leuten singen und sagen: / 'Ich hatte gesündigt und das Recht verdreht, / und er hat es mir nicht vergolten." },
      { number: 28, text: "Er hat mich erlöst vor dem Abstieg ins Grab, / und mein Leben schaut das Licht.'" },
      { number: 29, text: "Ja, das alles tut Gott / zwei- und dreimal mit dem Mann," },
      { number: 30, text: "um sein Leben vom Grab abzuwenden, / dass das Licht des Lebens ihm leuchte." },
      { number: 31, text: "Merke auf, Hiob, höre mir zu; / schweig, denn ich will reden!" },
      { number: 32, text: "Doch hast du Worte, so antworte mir! / Sprich, denn gern gäb ich dir recht!" },
      { number: 33, text: "Wenn nicht, so höre mir zu; / schweig, und ich zeige dir, was Weisheit ist!\"" },
    ] },
    { number: 34, verses: [
      { number: 1, text: "Elihu fuhr fort und sagte:", heading: "Elihus zweite Rede: Aufruf an die drei Freunde" },
      { number: 2, text: "\"Hört, ihr Weisen, meine Worte, / ihr Kundigen, gebt mir Gehör!" },
      { number: 3, text: "Denn das Ohr prüft die Worte, / der Gaumen kostet die Speise." },
      { number: 4, text: "Lasst uns prüfen, was recht ist, / was gut ist, zusammen erforschen!\"" },
      { number: 5, text: "\"Denn Hiob hat gesagt: 'Ich bin gerecht, / und Gott verweigert mir mein Recht.", heading: "Zurückweisung der Worte Hiobs" },
      { number: 6, text: "Sollte ich lügen über mein Recht? / Tödlich traf mich der Pfeil, obwohl ich ohne Schuld bin.'" },
      { number: 7, text: "Wo ist ein Mann wie Hiob, / der Hohn wie Wasser trinkt," },
      { number: 8, text: "der sich mit üblem Gesindel abgibt, / der Umgang mit Gottlosen hat?" },
      { number: 9, text: "Denn er hat gesagt: 'Es nützt einem nichts, wenn man Gott gefallen will.'\"" },
      { number: 10, text: "\"Darum hört mir zu, / ihr verständigen Männer! / Niemals wird Gott gottlos handeln, / der Allmächtige Unrecht tun.", heading: "Gott regiert vollkommen gerecht" },
      { number: 11, text: "Nein, was der Mensch tut, das vergilt er ihm; / er bekommt, was er verdient." },
      { number: 12, text: "Es ist gewiss: Gott handelt nicht gottlos, / der Allmächtige verdreht nicht das Recht.\"" },
      { number: 13, text: "\"Wer hat ihm die Erde anvertraut, / wer den ganzen Erdkreis hingestellt?", heading: "Gott erhält die ganze Welt" },
      { number: 14, text: "Wenn er nur an sich denken würde / und hielte seinen Lebenshauch zurück," },
      { number: 15, text: "dann käme alles Fleisch auf einen Schlag um, / und der Mensch würde wieder zu Staub.\"" },
      { number: 16, text: "\"Hast du Verstand, dann höre dies, / achte genau auf meine Worte!", heading: "Gott regiert mit vollkommenem Wissen" },
      { number: 17, text: "Kann denn herrschen, wer das Recht hasst? / Oder willst du den Gerechten und Mächtigen verdammen?" },
      { number: 18, text: "Darf man einen König Nichtsnutz nennen, / ist es recht, Edle gottlos zu heißen?" },
      { number: 19, text: "Er ergreift nicht für die Oberen Partei; / der Reiche gilt ihm nicht mehr als der Arme, / denn sie alle sind das Werk seiner Hände." },
      { number: 20, text: "Sie sterben plötzlich, mitten in der Nacht, / sie werden erschüttert und vergehen. / Mächtige entfernt er ohne Menschenhand." },
      { number: 21, text: "Seine Augen sind auf die Wege jedes Menschen gerichtet, / er sieht jeden Schritt, den sie tun." },
      { number: 22, text: "Da ist kein Dunkel und kein Schatten, / der die Bösen verbirgt." },
      { number: 23, text: "Er muss den Menschen nicht lang untersuchen, / bevor er vor Gott ins Gericht kommt." },
      { number: 24, text: "Gewaltige knickt er ohne Verhör / und stellt andere an ihren Platz." },
      { number: 25, text: "Weil er ihre Taten kennt, / stürzt er sie über Nacht um, / und sie werden zermalmt." },
      { number: 26, text: "Als Gottlose schlägt er sie nieder / am Ort, wo alle sie sehn," },
      { number: 27, text: "weil sie ihm nicht mehr folgten / und keinen seiner Wege bedachten." },
      { number: 28, text: "So dringt auch der Schrei der Armen zu ihm, / er hört das Geschrei der Gebeugten." },
      { number: 29, text: "Schafft er Ruhe, / wer will es verdammen? / Verbirgt er das Gesicht, / wer kann ihn schauen? / Doch er wacht über Völker und Menschen," },
      { number: 30, text: "dass kein Gewissenloser König wird / und dem Volk ein Fallstrick ist.\"" },
      { number: 31, text: "\"Hat Hiob denn zu Gott gesagt: / 'Ich trage es, ich will ja nichts Böses tun?", heading: "Hiobs folgenschwere Unterlassung" },
      { number: 32, text: "Zeig du mir, was ich nicht sehe! / Habe ich Unrecht getan, ich tu es nicht wieder.'" },
      { number: 33, text: "Soll Gott nach deinem Sinn vergelten, / weil du es verwirfst? / Du musst wählen und nicht ich. / Weißt du etwas, sag es an!" },
      { number: 34, text: "Verständige Leute werden mir sagen / und jeder Weise, der mir zuhört:" },
      { number: 35, text: "'Hiob redet nicht mit Verstand, / seine Worte waren unbedacht." },
      { number: 36, text: "Soll Hiob doch immer weiter geprüft werden, / weil er wie ein Gottloser spricht." },
      { number: 37, text: "Denn zu seiner Sünde fügt er Treubruch hinzu, / klatscht vor Hohn in die Hände, / führt viele Reden gegen Gott.'\"" },
    ] },
    { number: 35, verses: [
      { number: 1, text: "Elihu fuhr fort und sagte:", heading: "Elihus dritte Rede: Hiobs ungebührliche Worte" },
      { number: 2, text: "\"Hältst du das für richtig, / wenn du sagst: / 'Ich will mein Recht von Gott'," },
      { number: 3, text: "und wenn du sagst: 'Was macht es dir, / was nützt es mir, / wenn ich nicht sündige?'" },
      { number: 4, text: "Ich will dir Antwort geben / und deinen Freunden mit dir.\"" },
      { number: 5, text: "\"Blick zum Himmel auf und sieh / und schau die Wolken an! / Sie sind höher als du.", heading: "Wir nehmen und geben Gott nichts" },
      { number: 6, text: "Wenn du sündigst, was schadest du ihm; / verübst du viele Verbrechen, was tust du ihm an?" },
      { number: 7, text: "Wenn du gerecht bist, was gibst du ihm, / was empfängt er dadurch von dir?" },
      { number: 8, text: "Deine Bosheit schadet nur Menschen; / und nur Menschen nützt auch deine Gerechtigkeit.\"" },
      { number: 9, text: "\"Man schreit, dass viel Gewalt geschieht, / ruft um Hilfe vor der Willkür der Großen.", heading: "Gott ist nicht unser Diener" },
      { number: 10, text: "Aber keiner sagt: 'Wo ist Gott, mein Schöpfer, / der Lobgesänge gibt in der Nacht," },
      { number: 11, text: "der uns Besseres lehrt als die wilden Tiere / und klüger macht als die Vögel?'" },
      { number: 12, text: "Da schreien sie – doch er antwortet nicht – über den Hochmut der Bösen." },
      { number: 13, text: "Das Schreien ist umsonst, Gott hört es nicht, / der Allmächtige sieht es nicht an." },
      { number: 14, text: "Wenn du auch sagst, du kannst ihn nicht sehen; / dein Fall liegt ihm vor, warte auf ihn." },
      { number: 15, text: "Jetzt aber, weil sein Zorn nicht gestraft hat / und er den Übermut noch übersieht," },
      { number: 16, text: "reißt Hiob seinen Mund auf zu leerem Gerede, / macht viele Worte ohne Verstand.\"" },
    ] },
    { number: 36, verses: [
      { number: 1, text: "Elihu fuhr fort und sagte:", heading: "Das Leid weist uns zurecht (36-37)\nElihus letzte Rede: Gott ist gerecht" },
      { number: 2, text: "\"Warte ein wenig, / ich will's dir erklären, / denn es ist noch mehr zu sagen für Gott." },
      { number: 3, text: "Ich will mein Wissen von weither holen / und zeigen, dass mein Schöpfer gerecht ist." },
      { number: 4, text: "Das ist gewiss: Meine Worte trügen nicht. / Der, der alles Wissen hat, der ist bei dir." },
      { number: 5, text: "Ja, Gott ist mächtig / – und doch verachtet er niemand – / mächtig an Verstandeskraft." },
      { number: 6, text: "Den Gottlosen lässt er nicht leben, / doch dem Elenden schafft er das Recht." },
      { number: 7, text: "Von Gerechten wendet er seine Augen nicht ab; / zu Königen setzt er sie auf den Thron, / und sie werden für immer erhöht.\"" },
      { number: 8, text: "\"Und sind sie mit Fesseln gebunden, / in Stricken des Elends gefangen,", heading: "Gottes Züchtigung ist uns zum Heil" },
      { number: 9, text: "dann zeigt er ihnen ihr Tun, / ihre Vergehen und ihren Stolz;" },
      { number: 10, text: "dann öffnet er ihr Ohr für Zucht / und befiehlt ihnen, vom Bösen zu lassen." },
      { number: 11, text: "Wenn sie hören und sich unterwerfen, / vollenden sie ihre Tage im Glück / und ihre Jahre in Freude." },
      { number: 12, text: "Hören sie nicht, laufen sie in den Tod / und kommen im Unverstand um." },
      { number: 13, text: "Die Gottesverächter schnauben vor Wut, / rufen nicht um Hilfe, wenn er sie lähmt." },
      { number: 14, text: "Ihre Seele stirbt schon in der Jugend / und ihr Leben unter Prostituierten*.", footnotes: ["Prostituierte. Gemeint sind männliche Kultprostituierte."] },
      { number: 15, text: "Den Elenden rettet er durch sein Elend / und öffnet sein Ohr durch die Not.\"" },
      { number: 16, text: "\"Er lockt auch dich aus dem Rachen der Angst / in einen weiten Raum ohne Enge, / zur Ruhe am reich gedeckten Tisch.", heading: "Trotze Gott nicht länger!" },
      { number: 17, text: "Urteilst du so wie Gottlose es tun, / werden Urteil und Gericht dich ergreifen." },
      { number: 18, text: "Der Zorn verlocke dich ja nicht zum Hohn, / das hohe Lösegeld verführe dich nicht!" },
      { number: 19, text: "Kann dein Schreien dich aus der Not befreien, / kann es eigene Anstrengung schaffen?" },
      { number: 20, text: "Sehne nicht die Nacht herbei, / in der die Völker untergehen." },
      { number: 21, text: "Pass auf und wende dich nicht zu dem Bösen, / dass du es anstelle des Elends auswählst!\"" },
      { number: 22, text: "\"Gott ist erhaben in seiner Macht. / Wer ist ein Lehrer wie er?", heading: "Hab Ehrfurcht vor Gott!" },
      { number: 23, text: "Wer schreibt ihm seinen Weg vor, / und wer darf sagen: Du hast Unrecht getan?" },
      { number: 24, text: "Denk daran, sein Tun zu preisen, / das die Menschen besingen!" },
      { number: 25, text: "Alle Menschen haben es gesehen, / jeder kann es von ferne erblicken." },
      { number: 26, text: "Ja, Gott ist erhaben, wir fassen es nicht; / keiner erforscht die Zahl seiner Jahre.\"" },
      { number: 27, text: "\"Ja, er zieht Wassertropfen herauf, / ballt den Dunst zu Regen,", heading: "Die Schöpfung offenbart Gottes Weisheit und Macht" },
      { number: 28, text: "der dann aus den Wolken träufelt / und viele Menschen benetzt." },
      { number: 29, text: "Versteht man gar das Ausbreiten der Wolken, / das Donnerkrachen aus seinem Zelt?" },
      { number: 30, text: "Schau, mit Licht hat er sich umgeben / und den Grund des Meeres zugedeckt." },
      { number: 31, text: "Ja, damit richtet er die Völker – und gibt ihnen Nahrung im Überfluss." },
      { number: 32, text: "Seine Hände beherrschen den Blitz; / er befiehlt ihm, wen er treffen soll." },
      { number: 33, text: "Sein Rollen kündigt ihn an, / seinen Zorneseifer gegen die Bosheit." },
    ] },
    { number: 37, verses: [
      { number: 1, text: "Ja, auch mein Herz zittert dabei / und fängt wild zu schlagen an." },
      { number: 2, text: "Hört doch das Toben seiner Stimme, / das Grollen, das aus seinem Mund kommt." },
      { number: 3, text: "Über der ganzen Welt lässt er es los, / sein Blitz fährt bis zum Ende der Erde." },
      { number: 4, text: "Hinter ihm her brüllt der Donner, / er donnert mit seiner erhabenen Stimme. / Er hält sie nicht zurück, wenn sein Donner hallt." },
      { number: 5, text: "Gott donnert wunderbar mit seiner Stimme, / tut große Dinge, die man nicht versteht." },
      { number: 6, text: "Er spricht zum Schnee: 'Fall nieder zur Erde!' / und zum Regenschwall: 'Werde zur Sturzflut!'" },
      { number: 7, text: "Er versiegelt* die Hand jedes Menschen, / dass die Menschen merken: Sie sind sein Werk.", footnotes: ["versiegelt. Gott sorgt dafür, dass der Mensch seine Hand nicht rühren kann. Der Mensch ist angesichts der Naturgewalten, die etwas von Gottes Allmacht aufblitzen lassen, hilflos."] },
      { number: 8, text: "Da gehen die Tiere in ihr Versteck / und bleiben in ihren Höhlen." },
      { number: 9, text: "Aus dem Süden kommt der Sturm; / der Nordwind bringt Kälte." },
      { number: 10, text: "Durch Gottes Atem entsteht das Eis, / und die weite Fläche des Wassers erstarrt." },
      { number: 11, text: "Er belädt die Wolken mit Wasser / und schickt sie mit Blitzen umher." },
      { number: 12, text: "Sie zucken hin und her, / wie er sie lenkt, / dass sie alles tun, was er befiehlt / auf dem ganzen Erdenrund." },
      { number: 13, text: "Als Zuchtrute für seine Erde / oder zur Gnade lässt er sie kommen." },
      { number: 14, text: "Hör dir das an, Hiob! / Steh auf und betrachte Gottes Wunder!" },
      { number: 15, text: "Weißt du, wie Gott sie belädt / und das Licht seiner Wolken aufblitzen lässt?" },
      { number: 16, text: "Verstehst du das Schweben der Wolken, / die Wunder dessen, der alles weiß?" },
      { number: 17, text: "Du, dem die Kleidung zu warm wird, / wenn die Erde unter dem Südwind liegt." },
      { number: 18, text: "Kannst du gleich ihm den Lufthimmel wölben*, / fest wie einen gegossenen Spiegel*?", footnotes: ["wölben. Hebräisch: raka. Das ist verwandt mit rakia, Wölbung, von 1. Mose 1,6.", "Spiegel waren damals aus Metall."] },
      { number: 19, text: "Lass uns wissen: Was sollen wir ihm sagen? / Wir tappen doch im Dunkeln und wissen nichts." },
      { number: 20, text: "Muss man ihm sagen, dass ich rede? / Muss man erst sprechen, dass es mitgeteilt wird?" },
      { number: 21, text: "Jetzt sieht man das Licht nicht, / das hinter den Wolken glänzt; / doch dann kommt ein Wind auf und fegt sie weg." },
      { number: 22, text: "Aus dem Norden dringt ein goldener Schein; / Gott umgibt eine erschreckende Pracht." },
      { number: 23, text: "Den Allmächtigen begreifen wir nicht. / Er ist erhaben an Kraft und Gerechtigkeit; / das Recht beugt er nicht." },
      { number: 24, text: "Darum fürchten ihn die Menschen. / Ob einer weise ist, kümmert ihn nicht.\"" },
    ] },
    { number: 38, verses: [
      { number: 1, text: "Da antwortete Jahwe aus dem Sturm und sagte zu Hiob:", heading: "38-41: Die Rede Gottes\nKannst du die Schöpfung begreifen? (38-39)\nDie erste Rede Gottes aus dem Sturm" },
      { number: 2, text: "\"Wer verdunkelt den Rat / mit Reden ohne Einsicht?" },
      { number: 3, text: "Steh auf und zeig dich als Mann! / Dann will ich dich fragen, und du belehrst mich." },
      { number: 4, text: "Wo warst du, als ich die Erde gründete? / Sag an, wenn du es weißt!" },
      { number: 5, text: "Wer hat ihre Maße bestimmt? Weißt du es? / Wer hat die Messschnur über sie gespannt?" },
      { number: 6, text: "Wo sind ihre Pfeiler eingesenkt? / Wer hat ihren Eckstein gelegt," },
      { number: 7, text: "als alle Morgensterne jubelten / und alle Gottessöhne jauchzten?\"" },
      { number: 8, text: "\"Wer hat das Meer mit Toren verschlossen, / als es berstend aus dem Mutterleib schoss?", heading: "Gott, der Herr über die Erde" },
      { number: 9, text: "Ich machte die Wolken zu seinem Gewand, / das Wetterdunkel zu seiner Windel." },
      { number: 10, text: "Ich brach ihm eine Grenze aus dem Gestein, / setzte ihm Riegel und Tore." },
      { number: 11, text: "Ich sagte: 'Bis hierher und nicht weiter! / Hier bricht der Stolz deiner Wellen!'" },
      { number: 12, text: "Hast du je in deinem Leben dem Morgen geboten, / dem Frührot seinen Ort gezeigt," },
      { number: 13, text: "dass es die Säume der Erde erfasst, / um die Schuldigen herauszuschütteln?" },
      { number: 14, text: "Die Erde faltet sich wie Siegelton*; / wie im Prachtgewand steht alles da.", footnotes: ["Siegelton. Ton, in den ein Siegel eingedrückt wird."] },
      { number: 15, text: "Den Bösen wird ihr Licht entzogen, / es zerbricht der erhobene Arm*.", footnotes: ["der erhobene Arm. Das ist eine typisch hebräische Ausdrucksweise für das mutwillige Sündigen."] },
      { number: 16, text: "Bist du zu den Quellen des Meeres gekommen, / hast du den Grund der Fluten durchstreift?" },
      { number: 17, text: "Haben sich dir die Tore des Todes enthüllt, / hast du die Pforten der Schatten gesehen?" },
      { number: 18, text: "Hast du ermessen, wie breit die Erde ist? / Sag an, wenn du das alles weißt!" },
      { number: 19, text: "Wo ist der Weg zur Wohnung des Lichts? / Die Finsternis, wo hat sie ihren Ort?" },
      { number: 20, text: "Kannst du sie in ihr Gebiet begleiten, / kennst du die Wege zu ihrem Haus?" },
      { number: 21, text: "Du weißt es, du bist doch damals geboren, / und die Zahl deiner Tage ist groß!\"" },
      { number: 22, text: "\"Bist du zu den Speichern des Schnees gelangt? / Hast du die Kammern des Hagels gesehen,", heading: "Gott, der Herr unseres Himmels" },
      { number: 23, text: "den ich aufgespart habe für Zeiten der Not, / für den Tag des Kampfes und der Schlacht?" },
      { number: 24, text: "Wo ist der Weg, auf dem das Licht sich teilt, / der Ostwind sich über die Erde zerstreut?" },
      { number: 25, text: "Wer bricht der Regenflut die Bahn, / bahnt dem Gewitter seinen Weg?" },
      { number: 26, text: "Wer schickt den Regen auf unbewohntes Land, / auf die Wüste, wo kein Mensch ist?" },
      { number: 27, text: "Wer stillt den Durst der ausgedörrten Erde, / dass sie frisches Gras gedeihen lässt?" },
      { number: 28, text: "Hat der Regen einen Vater? / Wer hat die Tautropfen gezeugt?" },
      { number: 29, text: "Aus wessen Schoß kam das Eis hervor? / Wer hat den Reif des Himmels geboren?" },
      { number: 30, text: "Die Gewässer erstarren zu Stein / und die Fläche der Flut wird fest." },
      { number: 31, text: "Schnürst du die Bänder des Siebengestirns, / löst du die Fesseln des Orion?" },
      { number: 32, text: "Führst du die Tierkreisbilder zu ihrer Zeit aus, / leitest du den großen Bären samt seinen Jungen?" },
      { number: 33, text: "Kennst du die Gesetze des Himmels? / Setzt du seine Herrschaft auf der Erde durch?" },
      { number: 34, text: "Rufst du den Wolken dort Befehle zu, / dass ein Wasserschwall dich umhüllt?" },
      { number: 35, text: "Schickst du Blitze, dass sie niederfahren, / dass sie zu dir sagen: 'Hier sind wir!'?" },
      { number: 36, text: "Wer hat den Vögeln Weisheit gegeben, / wer mit Verstand die Fliegenden begabt?" },
      { number: 37, text: "Wer ist so weise, dass er die Wolken zählt? / Wer schüttet die Himmelskrüge aus," },
      { number: 38, text: "wenn der Boden hart ist wie Metall / und die Schollen sich verkleben?\"" },
      { number: 39, text: "\"Jagst du der Löwin ihre Beute? / Stillst du den jungen Löwen die Gier,", heading: "Gott, der Herr der Tiere" },
      { number: 40, text: "wenn sie in den Höhlen kauern, / im Dickicht auf der Lauer liegen?" },
      { number: 41, text: "Wer stellt dem Raben sein Futter bereit, / wenn seine Jungen zu Gott schreien, / herumflattern aus Mangel an Nahrung?" },
    ] },
    { number: 39, verses: [
      { number: 1, text: "Kennst du die Zeit, wann Steinböcke werfen? / Schaust du zu, wie die Hirschkühe kalben?" },
      { number: 2, text: "Zählst du die Monate, die sie trächtig sind; / kennst du die Zeit, wann sie werfen?" },
      { number: 3, text: "Sie krümmen sich, / stoßen ihre Jungen aus, / schütteln ihre Wehen ab." },
      { number: 4, text: "Ihre Jungen werden kräftig, / erstarken im Freien; / sie gehen davon und kehren nicht wieder." },
      { number: 5, text: "Wer hat den Wildesel frei laufen lassen, / wer hat die Fesseln des Wildlings gelöst?" },
      { number: 6, text: "Ich gab ihm die Steppe als Haus, / das Salzland zu seiner Wohnung." },
      { number: 7, text: "Er verlacht das Getümmel der Stadt, / das Geschrei des Treibers hört er nicht." },
      { number: 8, text: "Er streift durch die Berge nach Weide, / allem Grünen spürt er nach." },
      { number: 9, text: "Meinst du, der Wildstier wird dir dienen, / die Nacht an deiner Krippe verbringen?" },
      { number: 10, text: "Zwingst du ihn am Strick in die Furche, / pflügt er hinter dir die Täler durch?" },
      { number: 11, text: "Traust du ihm, weil er so stark ist, / überlässt du ihm deine Arbeit?" },
      { number: 12, text: "Vertraust du ihm, dass er deine Ernte einbringt / und sie zu deinem Dreschplatz zieht?" },
      { number: 13, text: "Die Straußhenne schlägt fröhlich die Flügel. / Sind es fromme Schwingen und Federn?" },
      { number: 14, text: "Nein, sie überlässt ihre Eier der Erde, / lässt sie erwärmen im Staub" },
      { number: 15, text: "und vergisst, dass ein Fuß sie zerdrücken / und ein Tier sie zertreten kann." },
      { number: 16, text: "Sie behandelt ihre Jungen hart, als wären es nicht ihre. / War ihre Mühe umsonst, kümmert es sie nicht," },
      { number: 17, text: "denn Gott hat ihr die Weisheit versagt, / er wies ihr keine Einsicht zu." },
      { number: 18, text: "Wenn sie dann aber in die Höhe schnellt, / verlacht sie Ross und Reiter." },
      { number: 19, text: "Gibst du dem Pferd seine Kraft, / kleidest du seinen Hals mit der Mähne?" },
      { number: 20, text: "Lässt du es wie die Heuschrecke springen? / Schrecklich sein prächtiges Schnauben!" },
      { number: 21, text: "Es scharrt den Boden und freut sich seiner Kraft, / es zieht aus, den Waffen entgegen." },
      { number: 22, text: "Es lacht über die Angst und fürchtet nichts / und weicht vor dem Schwert nicht zurück." },
      { number: 23, text: "Auf ihm rasselt der Köcher, / blitzen Wurfspieß und Speer." },
      { number: 24, text: "Wild und ungestüm fliegt es dahin, / lässt sich nicht halten, wenn das Horn ertönt." },
      { number: 25, text: "Bei jedem Hornstoß ruft es: Hui! / Es wittert von weitem die Schlacht, / den Donnerruf der Führer und das Kriegsgeschrei." },
      { number: 26, text: "Steigt der Falke durch deinen Verstand auf / und breitet seine Flügel in den Südwind aus?" },
      { number: 27, text: "Erhebt sich der Adler auf deinen Befehl / und baut sein Nest in der Höhe?" },
      { number: 28, text: "Auf Felsen wohnt und nächtigt er, / auf Felszahn und an steiler Wand." },
      { number: 29, text: "Von dort erspäht er den Fraß, / sein Auge sieht in die Ferne." },
      { number: 30, text: "Seine Jungen schlürfen Blut. / Wo es Erschlagene gibt, da ist er.\"" },
    ] },
    { number: 40, verses: [
      { number: 1, text: "So reagierte Jahwe auf Hiob und sagte:", heading: "Kannst du die Schöpfung beherrschen? (40-41)\nHiobs erste Antwort an Jahwe" },
      { number: 2, text: "\"Will der Tadler mit dem Allmächtigen streiten? / Der Gott Zurechtweisende antworte darauf!\"" },
      { number: 3, text: "Da erwiderte Hiob Jahwe:" },
      { number: 4, text: "\"Schau, ich bin zu gering. / Was soll ich erwidern? / Ich lege die Hand auf den Mund." },
      { number: 5, text: "Einmal habe ich geredet, ich wiederhole es nicht, / zweimal, und ich tu es nicht wieder.\"" },
      { number: 6, text: "Jahwe antwortete Hiob aus dem Sturm und sagte:", heading: "Die zweite Rede Gottes aus dem Sturm" },
      { number: 7, text: "\"Steh jetzt auf und zeig dich als Mann! / Dann will ich dich fragen, und du belehrst mich." },
      { number: 8, text: "Willst du im Ernst mein Recht bestreiten, / mich schuldig sehn, damit du Recht bekommst?" },
      { number: 9, text: "Sag, hast du einen Arm wie Gott, / kann deine Stimme donnern wie er?" },
      { number: 10, text: "Schmück dich doch mit Hoheit und Stolz, / kleide dich in Herrlichkeit und Pracht!" },
      { number: 11, text: "Gieß aus die Fluten deines Zorns, / sieh den Stolzen an und erniedrige ihn!" },
      { number: 12, text: "Beuge den Hochmut mit deinem Blick! / Tritt auf der Stelle die Gottlosen nieder!" },
      { number: 13, text: "Verscharr sie allesamt im Staub, / schließe sie im Verborgenen ein!" },
      { number: 14, text: "Dann will auch ich dich preisen, / es half dir ja deine Rechte!\"" },
      { number: 15, text: "\"Sieh doch den Behemot*, / den ich wie dich erschuf. / Gras frisst er wie das Rind.", heading: "Der Behemot", footnotes: ["Behemot ist die Mehrzahl vonbehema , Vieh. Es meint ein Ungetüm von Vieh, ein unbesiegbares Riesentier. Seine Beschreibung erinnert an einen Saurier."] },
      { number: 16, text: "Seine Kraft ist in den Lenden, / seine Stärke in den Muskeln seines Bauchs." },
      { number: 17, text: "Er streckt seinen Schwanz wie die Zeder. / Die Sehnen seiner Schenkel sind verflochten." },
      { number: 18, text: "Seine Knochen sind Röhren aus Bronze, / seine Gebeine wie eiserne Stäbe." },
      { number: 19, text: "Er ist das Erste von Gottes Geschöpfen. / Der ihn schuf, gab ihm sein Schwert." },
      { number: 20, text: "Das Futter tragen die Berge ihm zu, / dort, wo die Wildtiere spielen." },
      { number: 21, text: "Unter Lotosbüschen legt er sich nieder, / versteckt in Rohr und Sumpf." },
      { number: 22, text: "Lotosbüsche spenden ihm Schatten, / die Weiden am Bach umgeben ihn." },
      { number: 23, text: "Da schwillt der Strom! Er läuft nicht weg, hält still, / selbst wenn ein Sturzbach ihm ans Maul schießt." },
      { number: 24, text: "Kann man ihn fangen, wenn er die Augen offen hat, / ihm Stricke durch die Nase ziehn?\"" },
      { number: 25, text: "\"Ziehst du den Leviatan* mit der Angel herbei, / fasst du seine Zunge mit dem Seil?", heading: "Der Leviatan", footnotes: ["Leviatan. Der hebräische Ausdruck bedeutet \"der Gewundene\". Seine Beschreibung erinnert an einen riesigen Wassersaurier."] },
      { number: 26, text: "Ziehst du ihm einen Ring durch die Nase, / bohrst einen Haken durch seine Kiefer?" },
      { number: 27, text: "Wird er dich lang um Gnade bitten / und freundlich reden mit dir?" },
      { number: 28, text: "Wird er einen Bund mit dir schließen, / dass er für immer dein Sklave wird?" },
      { number: 29, text: "Spielst du mit ihm wie mit einem Vogel / und bindest ihn für deine Mädchen an?" },
      { number: 30, text: "Feilschen die Jagdgenossen um ihn, / verteilen sie ihn unter die Händler?" },
      { number: 31, text: "Spickst du seine Haut mit Spießen, / mit Harpunen seinen Kopf?" },
      { number: 32, text: "Leg nur deine Hand an ihn / und denk an den Kampf! / Du tust es sicher nicht wieder." },
    ] },
    { number: 41, verses: [
      { number: 1, text: "Sieh, die Hoffnung wird enttäuscht, / schon wer ihn sieht, wird niedergeworfen." },
      { number: 2, text: "Niemand ist so tollkühn, dass er ihn weckt!Und wer ist's, der vor mir besteht?" },
      { number: 3, text: "Wer hat mir je etwas gegeben, / das ich ihm zurückzahlen müsste?* / Alles unter dem Himmel gehört mir.", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 11,35."] },
      { number: 4, text: "Ich will nicht schweigen von ihm, / wie stark er ist und schön gebaut." },
      { number: 5, text: "Wer schälte ihm je das Oberkleid ab? / Wer greift ihm zwischen die Zähne?" },
      { number: 6, text: "Wer öffnet das Tor seines Rachens? / Rings um seine Zähne steht Schrecken." },
      { number: 7, text: "Stolz stehen die Rillen der Schilde, / mit festem Siegel verschlossen." },
      { number: 8, text: "Einer fügt sich an den andern, / kein Hauch dringt dazwischen." },
      { number: 9, text: "Sie hängen fest aneinander; / sie greifen ineinander und trennen sich nicht." },
      { number: 10, text: "Sein Niesen verstrahlt Licht, / und seine Augen sind wie Wimpern des Frührots." },
      { number: 11, text: "Fackeln fahren aus seinem Maul, / feurige Funken schießen heraus." },
      { number: 12, text: "Aus seinen Nüstern kommt Rauch / wie aus einem heißen Topf." },
      { number: 13, text: "Sein Atem entzündet Kohlen, / eine Flamme schlägt aus seinem Maul." },
      { number: 14, text: "In seinem Nacken wohnt Stärke, / vor ihm her hüpft die Angst." },
      { number: 15, text: "Sein Bauch ist straff und fest, / wie angegossen, unbewegt." },
      { number: 16, text: "Sein Herz ist fest wie Stein, / hart wie der untere Mühlstein." },
      { number: 17, text: "Selbst Helden graut es, wenn er sich erhebt, / vor Schreck ziehen sie sich zurück." },
      { number: 18, text: "Trifft man ihn, hält kein Schwert stand, / nicht Lanze noch Geschoss und Pfeil." },
      { number: 19, text: "Eisen hält er für Stroh, / Bronze für morsches Holz." },
      { number: 20, text: "Ein Pfeil verjagt ihn nicht, / Schleudersteine sind ihm wie Stoppeln." },
      { number: 21, text: "Für Stroh hält er die Keule, / er lacht über den Aufprall des Schwerts." },
      { number: 22, text: "Scharfe Scherben sind an seinem Bauch; / einen Dreschschlitten zieht er über den Schlamm." },
      { number: 23, text: "Er macht die Tiefe zu einem siedenden Kessel, / das Meer zu einem Salbentopf." },
      { number: 24, text: "Hinter sich lässt er eine leuchtende Spur, / sie erscheint wie Silberhaar." },
      { number: 25, text: "Auf der Erde ist keiner ihm gleich, / ein Geschöpf ohne Furcht." },
      { number: 26, text: "Auf alles Hohe blickt er herab, / ein König über das stolze Wild.\"" },
    ] },
    { number: 42, verses: [
      { number: 1, text: "Da erwiderte Hiob Jahwe und sagte:", heading: "42: Nachwort des Autors\nHiobs Unterwerfung" },
      { number: 2, text: "\"Ich weiß, dass du alles vermagst, / kein Plan ist unmöglich für dich." },
      { number: 3, text: "'Wer verhüllt da den Rat / mit Reden ohne Einsicht?' / Ja, ich habe geredet, was ich nicht verstand. / Es war zu wunderbar für mich, / ich begriff das alles nicht." },
      { number: 4, text: "Hör doch, ich will nun reden, / will dich fragen, dass du mich belehrst." },
      { number: 5, text: "Bloß mit dem Ohr hatte ich von dir gehört, / jetzt aber hat mein Auge dich geschaut." },
      { number: 6, text: "Darum unterwerfe ich mich / und bereue in Asche und Staub.\"" },
      { number: 7, text: "Nachdem Jahwe das alles zu Hiob gesagt hatte, wandte er sich an Elifas von Teman. \"Ich bin zornig über dich und deine beiden Freunde geworden\", sagte er, \"denn ihr habt nichts Verlässliches über mich gesagt wie mein Diener Hiob.", heading: "Hiobs Freunde werden versöhnt" },
      { number: 8, text: "Nehmt euch jetzt sieben Stiere und sieben Schafböcke, geht damit zu meinem Diener Hiob und opfert sie mir als Brandopfer für euch! Mein Diener Hiob soll für euch bitten, denn auf ihn will ich hören, damit ich euch nichts Schlimmes antue. Denn ihr habt nichts Verlässliches über mich gesagt wie mein Diener Hiob.\"" },
      { number: 9, text: "Da gingen Elifas von Teman, Bildad von Schuach und Zofar von Naama und taten, was Jahwe ihnen gesagt hatte. Und Jahwe hörte auf Hiob." },
      { number: 10, text: "Er wendete sein Geschick, als er für seine drei Freunde bat, und gab ihm doppelt so viel, wie er gehabt hatte." },
      { number: 11, text: "Da kamen alle seine Brüder und Schwestern und alle seine früheren Bekannten zu ihm. Sie speisten mit ihm in seinem Haus und bekundeten ihm ihre Teilnahme. Sie trösteten ihn wegen all des Unglücks, das Jahwe über ihn gebracht hatte. Jeder schenkte ihm eine Kesita* und einen goldenen Ring.", heading: "Gott segnet Hiob", footnotes: ["Kesita. Geldeinheit/Geldgewicht ist bis heute unbekannt."] },
      { number: 12, text: "Jahwe segnete Hiob danach mehr als zuvor. Er besaß schließlich 14.000 Schafe, 6000 Kamele, 2000 Rinder und 1000 Eselinnen." },
      { number: 13, text: "Er bekam noch sieben Söhne und drei Töchter." },
      { number: 14, text: "Die erste nannte er Jemima, Täubchen, die zweite Kezia, Zimtblüte, und die dritte Keren-Happuch, Salbhörnchen." },
      { number: 15, text: "Im ganzen Land gab es keine schöneren Frauen als Hiobs Töchter. Ihr Vater gab ihnen Erbbesitz wie ihren Brüdern." },
      { number: 16, text: "Hiob lebte danach noch 140 Jahre und sah seine Kinder und Enkel, vier Generationen." },
      { number: 17, text: "Er starb nach einem langen und erfüllten Leben." },
    ] },
  ],
};